// Environnement administratif (2e banque) : Constitution de 1958 article par article, bloc de constitutionnalité,
// référendums et révisions, histoire de la Ve République, exécutif, Parlement, Conseil constitutionnel, juridictions
// judiciaires et administratives, administration centrale et déconcentrée, AAI/API, organes de contrôle,
// réforme de l'État, fonction publique (statut, positions, droits et obligations, discipline, déontologie) et DGFiP.
// Faits vérifiés sur le texte de la Constitution (conseil-constitutionnel.fr), service-public.gouv.fr et Wikipédia.
BANK.push(
{id:"ad2-001",t:"admin",q:"Depuis la révision de 2008, quel article de la Constitution prévoit que « la loi favorise l'égal accès des femmes et des hommes aux mandats électoraux et fonctions électives » ?",o:["L'article 3","L'article 4","L'article 34","L'article 1er"],a:3,e:"Introduite à l'article 3 en 1999, la parité a été transférée à l'article 1er en 2008 et étendue aux responsabilités professionnelles et sociales.",u:["https://fr.wikipedia.org/wiki/Article_1er_de_la_Constitution_de_la_Cinqui%C3%A8me_R%C3%A9publique_fran%C3%A7aise"],s:"Constitution, art. 1er"},
{id:"ad2-002",t:"admin",q:"Depuis quelle révision constitutionnelle l'article 2 dispose-t-il que « la langue de la République est le français » ?",o:["La révision du 25 juin 1992","Le texte d'origine de 1958","La révision du 28 mars 2003","La révision du 23 juillet 2008"],a:0,e:"Ajout de la révision du 25 juin 1992, adoptée avant la ratification du traité de Maastricht.",u:["https://fr.wikipedia.org/wiki/Article_2_de_la_Constitution_de_la_Cinqui%C3%A8me_R%C3%A9publique_fran%C3%A7aise"],s:"Constitution, art. 2"},
{id:"ad2-003",t:"admin",q:"Selon l'article 5, le président de la République assure, par son arbitrage :",o:["la détermination et la conduite de la politique de la Nation","l'exécution des lois et le pouvoir réglementaire","le fonctionnement régulier des pouvoirs publics ainsi que la continuité de l'État","la représentation des collectivités territoriales"],a:2,e:"Art. 5. La politique de la Nation relève du Gouvernement (art. 20), l'exécution des lois du Premier ministre (art. 21) et la représentation des collectivités du Sénat (art. 24).",u:["https://fr.wikipedia.org/wiki/Article_5_de_la_Constitution_de_la_Cinqui%C3%A8me_R%C3%A9publique_fran%C3%A7aise"],s:"Constitution, art. 5"},
{id:"ad2-004",t:"admin",q:"Selon l'article 7, quand a lieu le second tour de l'élection présidentielle ?",o:["Le septième jour suivant le premier tour","Le quatorzième jour suivant le premier tour","Le vingt et unième jour suivant le premier tour","Un mois après le premier tour"],a:1,e:"Seuls peuvent s'y présenter les deux candidats arrivés en tête, après retrait éventuel de candidats plus favorisés.",u:["https://www.conseil-constitutionnel.fr/le-bloc-de-constitutionnalite/texte-integral-de-la-constitution-du-4-octobre-1958-en-vigueur"],s:"Constitution, art. 7"},
{id:"ad2-005",t:"admin",q:"Pendant une vacance de la présidence de la République, quels pouvoirs le président par intérim ne peut-il pas exercer ?",o:["La promulgation des lois","La présidence du Conseil des ministres","La signature des décrets délibérés en Conseil des ministres","Le référendum (art. 11) et la dissolution (art. 12)"],a:3,e:"Art. 7 al. 4. Pendant la vacance, ni la censure du Gouvernement (art. 49-50) ni une révision de la Constitution (art. 89) ne peuvent intervenir.",u:["https://www.conseil-constitutionnel.fr/le-bloc-de-constitutionnalite/texte-integral-de-la-constitution-du-4-octobre-1958-en-vigueur"],s:"Constitution, art. 7"},
{id:"ad2-006",t:"admin",q:"Selon l'article 8, comment prennent fin les fonctions du Premier ministre ?",o:["Le Président le révoque librement par décret","Elles prennent fin automatiquement après chaque élection sénatoriale","Le Président y met fin sur la présentation par le Premier ministre de la démission du Gouvernement","Le Conseil constitutionnel constate la fin de ses fonctions"],a:2,e:"En droit, le Président ne peut pas révoquer le Premier ministre ; hors cohabitation, il obtient en pratique sa démission.",u:["https://fr.wikipedia.org/wiki/Article_8_de_la_Constitution_de_la_Cinqui%C3%A8me_R%C3%A9publique_fran%C3%A7aise"],s:"Constitution, art. 8"},
{id:"ad2-007",t:"admin",q:"Sur proposition de qui le président de la République peut-il soumettre un projet de loi au référendum de l'article 11 ?",o:["Du Conseil constitutionnel","Du Gouvernement pendant la durée des sessions, ou des deux assemblées conjointement","D'un dixième des électeurs inscrits","Du seul Premier ministre, à tout moment"],a:1,e:"Art. 11 al. 1 : la proposition est publiée au Journal officiel ; la décision appartient au Président.",u:["https://fr.wikipedia.org/wiki/Article_11_de_la_Constitution_de_la_Cinqui%C3%A8me_R%C3%A9publique_fran%C3%A7aise"],s:"Constitution, art. 11"},
{id:"ad2-008",t:"admin",q:"Quel objet la révision du 4 août 1995 a-t-elle ajouté au champ du référendum de l'article 11 ?",o:["Les réformes relatives à la politique économique ou sociale de la Nation et aux services publics qui y concourent","L'organisation des pouvoirs publics","La ratification d'un traité ayant des incidences sur le fonctionnement des institutions","L'approbation d'un accord de Communauté"],a:0,e:"L'organisation des pouvoirs publics et la ratification de certains traités figuraient dès 1958 ; la politique « environnementale » a été ajoutée en 2008.",u:["https://fr.wikipedia.org/wiki/Article_11_de_la_Constitution_de_la_Cinqui%C3%A8me_R%C3%A9publique_fran%C3%A7aise"],s:"Constitution, art. 11"},
{id:"ad2-009",t:"admin",q:"Le référendum d'initiative partagée (art. 11 al. 3) suppose l'initiative d'un cinquième des membres du Parlement, soutenue par :",o:["un cinquième des électeurs inscrits","un dixième des électeurs inscrits sur les listes électorales","500 000 électeurs","un million de citoyens de plusieurs États membres"],a:1,e:"Soit environ 4,7 millions de soutiens. Créé en 2008, le dispositif est applicable depuis le 1er janvier 2015.",u:["https://fr.wikipedia.org/wiki/R%C3%A9f%C3%A9rendum_d%27initiative_partag%C3%A9e"],s:"Constitution, art. 11"},
{id:"ad2-010",t:"admin",q:"Sur quel sujet portait, en 2019, la première proposition de loi référendaire (RIP) à atteindre la phase de recueil des soutiens ?",o:["La réforme des retraites","La suppression du Sénat","Le caractère de service public des Aéroports de Paris (ADP)","L'interdiction du glyphosate"],a:2,e:"Elle n'a recueilli qu'environ 1,09 million de soutiens, loin des 4,7 millions requis.",u:["https://fr.wikipedia.org/wiki/R%C3%A9f%C3%A9rendum_d%27initiative_partag%C3%A9e"],s:"Banque administration"},
{id:"ad2-011",t:"admin",q:"Après une dissolution de l'Assemblée nationale, dans quel délai les élections générales doivent-elles avoir lieu ?",o:["Entre 8 et 15 jours après la dissolution","Entre 30 et 60 jours après la dissolution","Entre 2 et 3 mois après la dissolution","Entre 20 et 40 jours après la dissolution"],a:3,e:"Art. 12 al. 2. Aucune nouvelle dissolution n'est possible dans l'année qui suit ces élections.",u:["https://fr.wikipedia.org/wiki/Article_12_de_la_Constitution_de_la_Cinqui%C3%A8me_R%C3%A9publique_fran%C3%A7aise"],s:"Constitution, art. 12"},
{id:"ad2-012",t:"admin",q:"Selon l'article 13, lesquels de ces responsables sont nommés en Conseil des ministres ?",o:["Les préfets et les directeurs d'administration centrale","Les sous-préfets et les inspecteurs des finances publiques","Les maires et les présidents de conseil départemental","Les juges des tribunaux judiciaires"],a:0,e:"La liste comprend aussi les conseillers d'État, les ambassadeurs, les conseillers maîtres à la Cour des comptes, les recteurs et les officiers généraux.",u:["https://fr.wikipedia.org/wiki/Article_13_de_la_Constitution_de_la_Cinqui%C3%A8me_R%C3%A9publique_fran%C3%A7aise"],s:"Constitution, art. 13"},
{id:"ad2-013",t:"admin",q:"Pour certaines nominations (art. 13 al. 5), le président de la République ne peut nommer lorsque l'addition des votes négatifs des commissions compétentes des deux assemblées atteint au moins :",o:["la majorité absolue des suffrages exprimés","les deux tiers des membres des commissions","les trois cinquièmes des suffrages exprimés","la moitié des membres de chaque commission"],a:2,e:"Procédure créée en 2008 (avis public des commissions permanentes), appliquée par exemple aux nominations au Conseil constitutionnel.",u:["https://fr.wikipedia.org/wiki/Article_13_de_la_Constitution_de_la_Cinqui%C3%A8me_R%C3%A9publique_fran%C3%A7aise"],s:"Constitution, art. 13"},
{id:"ad2-014",t:"admin",q:"Pendant l'exercice des pouvoirs exceptionnels de l'article 16 :",o:["le Parlement est suspendu","le Parlement se réunit de plein droit et l'Assemblée nationale ne peut être dissoute","le Gouvernement est démissionnaire de droit","la Constitution peut être révisée par décret"],a:1,e:"Depuis 2008, le Conseil constitutionnel peut en outre être saisi après 30 jours pour vérifier si les conditions restent réunies.",u:["https://fr.wikipedia.org/wiki/Article_16_de_la_Constitution_de_la_Cinqui%C3%A8me_R%C3%A9publique_fran%C3%A7aise"],s:"Constitution, art. 16"},
{id:"ad2-015",t:"admin",q:"Depuis 2008, devant qui le président de la République peut-il prendre la parole en personne ?",o:["Devant l'Assemblée nationale, avant un vote de confiance","Devant le Sénat, lors des questions au Gouvernement","Devant le Conseil constitutionnel en séance publique","Devant le Parlement réuni en Congrès"],a:3,e:"Art. 18 al. 2 : sa déclaration peut donner lieu, hors sa présence, à un débat sans vote. Première application : Nicolas Sarkozy à Versailles, le 22 juin 2009.",u:["https://www.conseil-constitutionnel.fr/le-bloc-de-constitutionnalite/texte-integral-de-la-constitution-du-4-octobre-1958-en-vigueur"],s:"Constitution, art. 18"},
{id:"ad2-016",t:"admin",q:"Lequel de ces actes du président de la République est dispensé de contreseing ?",o:["La dissolution de l'Assemblée nationale","La nomination des ministres sur proposition du Premier ministre","La signature des ordonnances","La nomination des préfets"],a:0,e:"Art. 19 : sont dispensés les actes prévus aux articles 8 (al. 1, nomination du Premier ministre), 11, 12, 16, 18, 54, 56 et 61.",u:["https://fr.wikipedia.org/wiki/Article_19_de_la_Constitution_de_la_Cinqui%C3%A8me_R%C3%A9publique_fran%C3%A7aise"],s:"Constitution, art. 19"},
{id:"ad2-017",t:"admin",q:"Selon l'article 21, qui exerce, sous réserve de l'article 13, le pouvoir réglementaire ?",o:["Le président de la République","Chaque ministre dans son domaine","Le Premier ministre","Le Conseil d'État"],a:2,e:"Le Premier ministre exerce le pouvoir réglementaire de droit commun ; le Président signe les décrets délibérés en Conseil des ministres (art. 13).",u:["https://fr.wikipedia.org/wiki/Article_21_de_la_Constitution_de_la_Cinqui%C3%A8me_R%C3%A9publique_fran%C3%A7aise"],s:"Constitution, art. 21"},
{id:"ad2-018",t:"admin",q:"Selon l'article 23, les fonctions de membre du Gouvernement sont incompatibles avec :",o:["un mandat de conseiller municipal","l'appartenance à un parti politique","la qualité d'ancien fonctionnaire","l'exercice de tout mandat parlementaire"],a:3,e:"Elles le sont aussi avec toute fonction de représentation professionnelle nationale, tout emploi public et toute activité professionnelle.",u:["https://www.conseil-constitutionnel.fr/le-bloc-de-constitutionnalite/texte-integral-de-la-constitution-du-4-octobre-1958-en-vigueur"],s:"Constitution, art. 23"},
{id:"ad2-019",t:"admin",q:"Quelle immunité protège un parlementaire contre toute poursuite pour les opinions ou votes émis dans l'exercice de ses fonctions ?",o:["L'irresponsabilité","L'inviolabilité","L'inamovibilité","Le privilège de juridiction"],a:0,e:"L'irresponsabilité (art. 26 al. 1) est absolue et permanente ; l'inviolabilité (al. 2) protège contre les arrestations sans autorisation du bureau de l'assemblée.",u:["https://fr.wikipedia.org/wiki/Article_26_de_la_Constitution_de_la_Cinqui%C3%A8me_R%C3%A9publique_fran%C3%A7aise"],s:"Constitution, art. 26"},
{id:"ad2-020",t:"admin",q:"Depuis la révision de 1995, quand s'ouvre et se termine la session ordinaire unique du Parlement ?",o:["Du 1er septembre au 31 juillet","Du premier jour ouvrable d'octobre au dernier jour ouvrable de juin","Du premier mardi d'octobre au 20 décembre","Du 1er janvier au 31 décembre"],a:1,e:"Art. 28 : chaque assemblée ne peut tenir plus de 120 jours de séance pendant cette session.",u:["https://www.conseil-constitutionnel.fr/le-bloc-de-constitutionnalite/texte-integral-de-la-constitution-du-4-octobre-1958-en-vigueur"],s:"Constitution, art. 28"},
{id:"ad2-021",t:"admin",q:"Pour lequel de ces domaines l'article 34 réserve-t-il à la loi seulement la détermination des « principes fondamentaux » ?",o:["L'assiette et le taux des impôts","La détermination des crimes et délits","L'enseignement","La nationalité"],a:2,e:"Dans ces matières (enseignement, droit du travail, libre administration des collectivités…), le règlement fixe le reste ; pour les autres, la loi fixe les règles.",u:["https://fr.wikipedia.org/wiki/Article_34_de_la_Constitution_de_la_Cinqui%C3%A8me_R%C3%A9publique_fran%C3%A7aise"],s:"Constitution, art. 34"},
{id:"ad2-022",t:"admin",q:"Que réserve l'article 34 à la loi au sujet des fonctionnaires civils et militaires de l'État ?",o:["L'organisation interne de chaque service","Les garanties fondamentales qui leur sont accordées","La valeur du point d'indice","Les modalités de leur entretien professionnel"],a:1,e:"La loi fixe les règles concernant « les garanties fondamentales accordées aux fonctionnaires civils et militaires de l'État ».",u:["https://fr.wikipedia.org/wiki/Article_34_de_la_Constitution_de_la_Cinqui%C3%A8me_R%C3%A9publique_fran%C3%A7aise"],s:"Constitution, art. 34"},
{id:"ad2-023",t:"admin",q:"Un texte de forme législative adopté après 1958 dans une matière réglementaire peut être modifié par décret si :",o:["le Conseil constitutionnel a déclaré qu'il a un caractère réglementaire","le Conseil d'État l'a annulé","le Parlement ne s'y oppose pas dans un délai d'un mois","le président de la République l'a promulgué"],a:0,e:"Art. 37 al. 2 (« délégalisation »). Pour les textes antérieurs à la Constitution, un décret pris après avis du Conseil d'État suffit.",u:["https://fr.wikipedia.org/wiki/Article_37_de_la_Constitution_de_la_Cinqui%C3%A8me_R%C3%A9publique_fran%C3%A7aise"],s:"Constitution, art. 37"},
{id:"ad2-024",t:"admin",q:"Comment sont prises les ordonnances de l'article 38 ?",o:["Par le Premier ministre seul, sans consultation","Par les commissions permanentes du Parlement","Par le Président, après avis du Conseil constitutionnel","En Conseil des ministres, après avis du Conseil d'État"],a:3,e:"Elles entrent en vigueur dès leur publication mais deviennent caduques si le projet de loi de ratification n'est pas déposé à temps.",u:["https://fr.wikipedia.org/wiki/Article_38_de_la_Constitution_de_la_Cinqui%C3%A8me_R%C3%A9publique_fran%C3%A7aise"],s:"Constitution, art. 38"},
{id:"ad2-025",t:"admin",q:"Un projet de loi ayant pour principal objet l'organisation des collectivités territoriales est soumis en premier lieu :",o:["à l'Assemblée nationale","au Conseil économique, social et environnemental","au Sénat","au Comité des finances locales"],a:2,e:"Art. 39 al. 2. Les projets de loi de finances et de financement de la sécurité sociale sont, eux, soumis d'abord à l'Assemblée nationale.",u:["https://fr.wikipedia.org/wiki/Article_39_de_la_Constitution_de_la_Cinqui%C3%A8me_R%C3%A9publique_fran%C3%A7aise"],s:"Constitution, art. 39"},
{id:"ad2-026",t:"admin",q:"Depuis la révision de 2008, combien de commissions permanentes chaque assemblée peut-elle compter au plus ?",o:["8","6","10","12"],a:0,e:"Art. 43 (le plafond était de 6 auparavant). Un texte peut aussi être renvoyé à une commission spéciale.",u:["https://fr.wikipedia.org/wiki/Article_43_de_la_Constitution_de_la_Cinqui%C3%A8me_R%C3%A9publique_fran%C3%A7aise"],s:"Constitution, art. 43"},
{id:"ad2-027",t:"admin",q:"Comment appelle-t-on la procédure par laquelle, à la demande du Gouvernement, l'assemblée se prononce par un seul vote sur tout ou partie d'un texte en ne retenant que les amendements qu'il a proposés ou acceptés ?",o:["L'engagement de responsabilité (art. 49 al. 3)","La procédure accélérée (art. 45)","La nouvelle délibération (art. 10)","Le vote bloqué (art. 44 al. 3)"],a:3,e:"Le vote bloqué ne met pas en jeu la responsabilité du Gouvernement, contrairement au 49.3.",u:["https://fr.wikipedia.org/wiki/Article_44_de_la_Constitution_de_la_Cinqui%C3%A8me_R%C3%A9publique_fran%C3%A7aise"],s:"Constitution, art. 44"},
{id:"ad2-028",t:"admin",q:"Selon l'article 45, en première lecture, un amendement est recevable dès lors qu'il présente :",o:["un lien direct avec l'article qu'il modifie","un lien, même indirect, avec le texte déposé ou transmis","l'accord préalable du Gouvernement","un coût inférieur à un seuil fixé par la loi organique"],a:1,e:"Les amendements sans aucun lien (« cavaliers législatifs ») sont censurés par le Conseil constitutionnel.",u:["https://fr.wikipedia.org/wiki/Article_45_de_la_Constitution_de_la_Cinqui%C3%A8me_R%C3%A9publique_fran%C3%A7aise"],s:"Constitution, art. 45"},
{id:"ad2-029",t:"admin",q:"Pour une proposition de loi, qui peut, depuis 2008, provoquer la réunion d'une commission mixte paritaire ?",o:["Le président du Sénat seul","Le Conseil constitutionnel","Soixante députés et soixante sénateurs","Les présidents des deux assemblées agissant conjointement"],a:3,e:"Pour un projet de loi, cette faculté appartient au Premier ministre (art. 45 al. 2).",u:["https://fr.wikipedia.org/wiki/Article_45_de_la_Constitution_de_la_Cinqui%C3%A8me_R%C3%A9publique_fran%C3%A7aise"],s:"Constitution, art. 45"},
{id:"ad2-030",t:"admin",q:"Faute d'accord entre les deux assemblées, à quelle majorité l'Assemblée nationale peut-elle adopter une loi organique en dernière lecture ?",o:["La majorité des suffrages exprimés","Les trois cinquièmes des suffrages exprimés","La majorité absolue de ses membres","Les deux tiers de ses membres"],a:2,e:"Art. 46 al. 3. Les lois organiques relatives au Sénat doivent, elles, être votées dans les mêmes termes par les deux assemblées.",u:["https://www.conseil-constitutionnel.fr/le-bloc-de-constitutionnalite/texte-integral-de-la-constitution-du-4-octobre-1958-en-vigueur"],s:"Constitution, art. 46"},
{id:"ad2-031",t:"admin",q:"Selon l'article 48, sur quatre semaines de séance, combien sont réservées par priorité aux textes et débats inscrits par le Gouvernement ?",o:["Une","Deux","Trois","Quatre"],a:1,e:"Une semaine sur quatre est réservée au contrôle et à l'évaluation, et un jour par mois aux groupes d'opposition et minoritaires (ordre du jour partagé depuis 2008).",u:["https://fr.wikipedia.org/wiki/Article_48_de_la_Constitution_de_la_Cinqui%C3%A8me_R%C3%A9publique_fran%C3%A7aise"],s:"Constitution, art. 48"},
{id:"ad2-032",t:"admin",q:"Sur quoi le Premier ministre engage-t-il la responsabilité du Gouvernement au titre de l'article 49 alinéa 1 ?",o:["Sur son programme ou éventuellement sur une déclaration de politique générale","Sur le vote d'un projet de loi de finances","Sur une motion de censure déposée par l'opposition","Sur un projet de révision constitutionnelle"],a:0,e:"Après délibération du Conseil des ministres, devant l'Assemblée nationale ; un vote défavorable oblige le Gouvernement à démissionner (art. 50).",u:["https://fr.wikipedia.org/wiki/Article_49_de_la_Constitution_de_la_Cinqui%C3%A8me_R%C3%A9publique_fran%C3%A7aise"],s:"Constitution, art. 49"},
{id:"ad2-033",t:"admin",q:"Le 8 septembre 2025, comment le gouvernement de François Bayrou a-t-il été renversé ?",o:["Par une motion de censure spontanée (art. 49 al. 2)","Par une motion de censure après un 49.3","Par un vote de confiance négatif (art. 49 al. 1)","Par la dissolution de l'Assemblée nationale"],a:2,e:"364 voix contre, 194 pour : c'est le premier gouvernement de la Ve République contraint à démissionner sur le fondement de l'article 49 alinéa 1.",u:["https://fr.wikipedia.org/wiki/Gouvernement_Fran%C3%A7ois_Bayrou"],s:"Banque administration"},
{id:"ad2-034",t:"admin",q:"Pour être recevable, une motion de censure spontanée (art. 49 al. 2) doit être signée par au moins :",o:["soixante députés","un cinquième des membres de l'Assemblée nationale","la majorité absolue des députés","un dixième des membres de l'Assemblée nationale"],a:3,e:"Soit 58 députés sur 577. Le vote ne peut avoir lieu que 48 heures après le dépôt.",u:["https://fr.wikipedia.org/wiki/Article_49_de_la_Constitution_de_la_Cinqui%C3%A8me_R%C3%A9publique_fran%C3%A7aise"],s:"Constitution, art. 49"},
{id:"ad2-035",t:"admin",q:"Depuis 2008, en dehors des projets de loi de finances et de financement de la sécurité sociale, le Premier ministre peut recourir à l'article 49 alinéa 3 :",o:["sans aucune limite","pour un seul autre projet ou proposition de loi par session","uniquement pendant les sessions extraordinaires","pour trois textes par session"],a:1,e:"Le texte est considéré comme adopté, sauf si une motion de censure déposée dans les 24 heures est votée.",u:["https://fr.wikipedia.org/wiki/Article_49_de_la_Constitution_de_la_Cinqui%C3%A8me_R%C3%A9publique_fran%C3%A7aise"],s:"Constitution, art. 49"},
{id:"ad2-036",t:"admin",q:"Si le Sénat désapprouve une déclaration de politique générale que le Premier ministre lui a soumise (art. 49 al. 4) :",o:["le Gouvernement n'est pas tenu de démissionner","le Gouvernement doit démissionner","l'Assemblée nationale est dissoute","le Sénat peut ensuite voter une motion de censure"],a:0,e:"Le Gouvernement n'est politiquement responsable que devant l'Assemblée nationale.",u:["https://fr.wikipedia.org/wiki/Article_49_de_la_Constitution_de_la_Cinqui%C3%A8me_R%C3%A9publique_fran%C3%A7aise"],s:"Constitution, art. 49"},
{id:"ad2-037",t:"admin",q:"Que permet l'article 50-1, créé en 2008 ?",o:["Un vote de confiance obligatoire après chaque remaniement","La censure du Gouvernement par le Sénat","Un référendum sur une question de politique générale","Une déclaration du Gouvernement sur un sujet déterminé, suivie d'un débat et éventuellement d'un vote, sans engager sa responsabilité"],a:3,e:"Le Gouvernement peut le faire de sa propre initiative ou à la demande d'un groupe parlementaire.",u:["https://fr.wikipedia.org/wiki/Article_50-1_de_la_Constitution_de_la_Cinqui%C3%A8me_R%C3%A9publique_fran%C3%A7aise"],s:"Constitution, art. 50-1"},
{id:"ad2-038",t:"admin",q:"Dans quelle situation une commission d'enquête parlementaire ne peut-elle pas être créée ?",o:["Sur des faits donnant lieu à des poursuites judiciaires en cours","Sur le fonctionnement d'un service public","Sur la gestion d'une entreprise publique","À l'initiative d'un groupe d'opposition"],a:0,e:"Ordonnance du 17 novembre 1958, art. 6. La mission d'une commission d'enquête prend fin au plus tard six mois après sa création.",s:"Banque administration"},
{id:"ad2-039",t:"admin",q:"Que prévoit l'article 53 de la Constitution ?",o:["Les traités ont une autorité supérieure à celle des lois","Certains traités (paix, commerce, engageant les finances de l'État…) ne peuvent être ratifiés qu'en vertu d'une loi","Le Conseil constitutionnel peut être saisi d'un engagement international","La République participe à l'Union européenne"],a:1,e:"Les autres propositions renvoient aux articles 55, 54 et 88-1.",u:["https://fr.wikipedia.org/wiki/Article_53_de_la_Constitution_de_la_Cinqui%C3%A8me_R%C3%A9publique_fran%C3%A7aise"],s:"Constitution, art. 53"},
{id:"ad2-040",t:"admin",q:"Qui nomme le président du Conseil constitutionnel ?",o:["Les membres du Conseil, par élection","Le président du Sénat","Le président de la République","Le Parlement réuni en Congrès"],a:2,e:"Art. 56 : il a voix prépondérante en cas de partage.",u:["https://fr.wikipedia.org/wiki/Conseil_constitutionnel_(France)"],s:"Constitution, art. 56"},
{id:"ad2-041",t:"admin",q:"Lequel de ces textes doit obligatoirement être soumis au Conseil constitutionnel avant sa mise en application ?",o:["Une loi ordinaire","Un décret en Conseil d'État","Le règlement d'une assemblée parlementaire","Une ordonnance de l'article 38"],a:2,e:"Art. 61 al. 1 : de même pour les lois organiques et les propositions de loi référendaires (RIP).",u:["https://fr.wikipedia.org/wiki/Article_61_de_la_Constitution_de_la_Cinqui%C3%A8me_R%C3%A9publique_fran%C3%A7aise"],s:"Constitution, art. 61"},
{id:"ad2-042",t:"admin",q:"Dans quel délai le Conseil constitutionnel statue-t-il sur une QPC qui lui est transmise ?",o:["Trois mois","Un mois","Huit jours","Six mois"],a:0,e:"Loi organique du 10 décembre 2009 ; le Conseil d'État ou la Cour de cassation dispose lui aussi de trois mois pour décider du renvoi.",u:["https://fr.wikipedia.org/wiki/Question_prioritaire_de_constitutionnalit%C3%A9"],s:"Banque administration"},
{id:"ad2-043",t:"admin",q:"Laquelle de ces conditions n'est pas requise pour qu'une QPC soit transmise ?",o:["La disposition est applicable au litige ou à la procédure","Elle n'a pas déjà été déclarée conforme à la Constitution, sauf changement des circonstances","La question n'est pas dépourvue de caractère sérieux","La disposition contestée doit avoir été adoptée depuis moins de cinq ans"],a:3,e:"Aucune condition d'ancienneté n'existe : une loi très ancienne peut faire l'objet d'une QPC.",u:["https://fr.wikipedia.org/wiki/Question_prioritaire_de_constitutionnalit%C3%A9"],s:"Banque administration"},
{id:"ad2-044",t:"admin",q:"Une disposition déclarée inconstitutionnelle à la suite d'une QPC est :",o:["annulée rétroactivement dans tous les cas","abrogée à compter de la publication de la décision ou d'une date ultérieure qu'elle fixe","maintenue jusqu'à ce que le Parlement la modifie","suspendue jusqu'à un référendum"],a:1,e:"Art. 62 al. 2. Une disposition censurée avant promulgation (art. 61) ne peut être ni promulguée ni appliquée.",u:["https://fr.wikipedia.org/wiki/Article_62_de_la_Constitution_de_la_Cinqui%C3%A8me_R%C3%A9publique_fran%C3%A7aise"],s:"Constitution, art. 62"},
{id:"ad2-045",t:"admin",q:"Quelle garantie l'article 64 accorde-t-il aux magistrats du siège ?",o:["L'irresponsabilité pénale","L'élection par leurs pairs","L'inamovibilité","L'immunité parlementaire"],a:2,e:"Un magistrat du siège ne peut recevoir une affectation nouvelle, même en avancement, sans son consentement.",u:["https://fr.wikipedia.org/wiki/Article_64_de_la_Constitution_de_la_Cinqui%C3%A8me_R%C3%A9publique_fran%C3%A7aise"],s:"Constitution, art. 64"},
{id:"ad2-046",t:"admin",q:"Depuis la révision de 2008, qui préside la formation du Conseil supérieur de la magistrature compétente à l'égard des magistrats du siège ?",o:["Le premier président de la Cour de cassation","Le président de la République","Le garde des Sceaux","Le vice-président du Conseil d'État"],a:0,e:"La formation compétente pour le parquet est présidée par le procureur général près la Cour de cassation ; le président de la République ne préside plus le CSM.",u:["https://fr.wikipedia.org/wiki/Conseil_sup%C3%A9rieur_de_la_magistrature_(France)"],s:"Constitution, art. 65"},
{id:"ad2-047",t:"admin",q:"En quelle année l'interdiction de la peine de mort a-t-elle été inscrite dans la Constitution ?",o:["1981","2007","1992","2008"],a:1,e:"Art. 66-1, issu de la révision du 23 février 2007 ; l'abolition elle-même date de la loi du 9 octobre 1981.",u:["https://www.conseil-constitutionnel.fr/le-bloc-de-constitutionnalite/texte-integral-de-la-constitution-du-4-octobre-1958-en-vigueur"],s:"Constitution, art. 66-1"},
{id:"ad2-048",t:"admin",q:"Pendant son mandat, le président de la République peut-il être poursuivi devant une juridiction pour des actes étrangers à ses fonctions ?",o:["Oui, devant la Cour de justice de la République","Oui, devant les juridictions de droit commun","Non, jamais, même après la fin de son mandat","Non : les procédures sont suspendues et peuvent reprendre un mois après la fin de son mandat"],a:3,e:"Art. 67 (révision du 23 février 2007) : tout délai de prescription ou de forclusion est suspendu.",u:["https://www.conseil-constitutionnel.fr/le-bloc-de-constitutionnalite/texte-integral-de-la-constitution-du-4-octobre-1958-en-vigueur"],s:"Constitution, art. 67"},
{id:"ad2-049",t:"admin",q:"Depuis 2007, pour quel motif le président de la République peut-il être destitué ?",o:["Un manquement à ses devoirs manifestement incompatible avec l'exercice de son mandat","La haute trahison","Une condamnation pénale définitive","La perte de la majorité à l'Assemblée nationale"],a:0,e:"Avant 2007, seule la « haute trahison » permettait de le mettre en cause. La destitution est votée à la majorité des deux tiers.",u:["https://fr.wikipedia.org/wiki/Article_68_de_la_Constitution_de_la_Cinqui%C3%A8me_R%C3%A9publique_fran%C3%A7aise"],s:"Constitution, art. 68"},
{id:"ad2-050",t:"admin",q:"Qui préside la Haute Cour appelée à se prononcer sur la destitution du président de la République ?",o:["Le président du Sénat","Le premier président de la Cour de cassation","Le président du Conseil constitutionnel","Le président de l'Assemblée nationale"],a:3,e:"Art. 68 : le Parlement constitué en Haute Cour statue dans un délai d'un mois, à bulletins secrets.",u:["https://fr.wikipedia.org/wiki/Article_68_de_la_Constitution_de_la_Cinqui%C3%A8me_R%C3%A9publique_fran%C3%A7aise"],s:"Constitution, art. 68"},
{id:"ad2-051",t:"admin",q:"Combien de juges composent la Cour de justice de la République ?",o:["9","12","15","24"],a:2,e:"12 parlementaires (6 députés et 6 sénateurs) et 3 magistrats du siège à la Cour de cassation, dont l'un la préside (art. 68-2).",u:["https://fr.wikipedia.org/wiki/Cour_de_justice_de_la_R%C3%A9publique"],s:"Constitution, art. 68-2"},
{id:"ad2-052",t:"admin",q:"Qui la Cour de justice de la République juge-t-elle ?",o:["Le président de la République, pour haute trahison","Les membres du Gouvernement, pour les crimes et délits commis dans l'exercice de leurs fonctions","Les parlementaires, pour leurs votes","Les magistrats, pour leurs fautes disciplinaires"],a:1,e:"Art. 68-1. Elle a été créée par la révision du 27 juillet 1993 ; toute personne lésée peut saisir sa commission des requêtes.",u:["https://fr.wikipedia.org/wiki/Cour_de_justice_de_la_R%C3%A9publique"],s:"Constitution, art. 68-1"},
{id:"ad2-053",t:"admin",q:"Depuis la loi organique du 15 janvier 2021, combien de membres compte le Conseil économique, social et environnemental ?",o:["175","233","348","100"],a:0,e:"La Constitution plafonne leur nombre à 233 (art. 71).",u:["https://fr.wikipedia.org/wiki/Conseil_%C3%A9conomique,_social_et_environnemental"],s:"Banque administration"},
{id:"ad2-054",t:"admin",q:"Depuis 2021, par combien de personnes une pétition doit-elle au moins être signée pour saisir le CESE ?",o:["500 000","1 million","50 000","150 000"],a:3,e:"Personnes âgées de 16 ans ou plus, de nationalité française ou résidant régulièrement en France (art. 69 et loi organique du 15 janvier 2021).",u:["https://fr.wikipedia.org/wiki/Conseil_%C3%A9conomique,_social_et_environnemental"],s:"Banque administration"},
{id:"ad2-055",t:"admin",q:"Pour quelle durée le Défenseur des droits est-il nommé par le président de la République ?",o:["Cinq ans, renouvelable une fois","Six ans, non renouvelable","Neuf ans, non renouvelable","Trois ans, renouvelable"],a:1,e:"Art. 71-1 ; il rend compte de son activité au président de la République et au Parlement.",u:["https://fr.wikipedia.org/wiki/D%C3%A9fenseur_des_droits"],s:"Constitution, art. 71-1"},
{id:"ad2-056",t:"admin",q:"Lequel de ces organismes n'a pas été absorbé par le Défenseur des droits en 2011 ?",o:["Le Médiateur de la République","La HALDE (lutte contre les discriminations)","La CNIL","Le Défenseur des enfants"],a:2,e:"Le Défenseur des droits a aussi repris la Commission nationale de déontologie de la sécurité ; la CNIL et le Contrôleur général des lieux de privation de liberté sont restés distincts.",u:["https://fr.wikipedia.org/wiki/D%C3%A9fenseur_des_droits"],s:"Banque administration"},
{id:"ad2-057",t:"admin",q:"À qui appartient l'initiative de la révision de la Constitution ?",o:["Au seul président de la République","Au Conseil constitutionnel et au Parlement","Au président de la République sur proposition du Premier ministre, et aux membres du Parlement","Aux citoyens, par une pétition d'un million d'électeurs"],a:2,e:"Art. 89 al. 1. Une proposition de révision d'origine parlementaire ne peut être approuvée que par référendum.",u:["https://fr.wikipedia.org/wiki/Article_89_de_la_Constitution_de_la_Cinqui%C3%A8me_R%C3%A9publique_fran%C3%A7aise"],s:"Constitution, art. 89"},
{id:"ad2-058",t:"admin",q:"Selon l'article 89, que ne peut faire l'objet d'aucune révision ?",o:["Le mode d'élection du président de la République","La forme républicaine du Gouvernement","Le nombre de membres du Conseil constitutionnel","La durée du mandat des députés"],a:1,e:"De plus, aucune révision ne peut être engagée ou poursuivie lorsqu'il est porté atteinte à l'intégrité du territoire.",u:["https://fr.wikipedia.org/wiki/Article_89_de_la_Constitution_de_la_Cinqui%C3%A8me_R%C3%A9publique_fran%C3%A7aise"],s:"Constitution, art. 89"},
{id:"ad2-059",t:"admin",q:"Quel est le bureau du Parlement réuni en Congrès ?",o:["Celui du Sénat","Celui du Conseil constitutionnel","Un bureau élu pour chaque réunion","Celui de l'Assemblée nationale"],a:3,e:"Art. 89 al. 3 : le Congrès, réuni à Versailles, est donc présidé par le président de l'Assemblée nationale.",u:["https://fr.wikipedia.org/wiki/Article_89_de_la_Constitution_de_la_Cinqui%C3%A8me_R%C3%A9publique_fran%C3%A7aise"],s:"Constitution, art. 89"},
{id:"ad2-060",t:"admin",q:"Lorsque l'intervention des forces armées à l'étranger excède quatre mois, sa prolongation :",o:["est soumise à l'autorisation du Parlement","est décidée par le seul président de la République","requiert un référendum","est autorisée par le Conseil de défense"],a:0,e:"Art. 35 (2008) : le Gouvernement informe le Parlement au plus tard 3 jours après le début de l'intervention.",u:["https://www.conseil-constitutionnel.fr/le-bloc-de-constitutionnalite/texte-integral-de-la-constitution-du-4-octobre-1958-en-vigueur"],s:"Constitution, art. 35"},
{id:"ad2-061",t:"admin",q:"Quelle décision du Conseil constitutionnel du 16 juillet 1971 a fait entrer le Préambule dans le bloc de constitutionnalité ?",o:["La décision « IVG »","La décision « Nationalisations »","La décision « Maastricht »","La décision « Liberté d'association »"],a:3,e:"Le Conseil a censuré une loi soumettant la création des associations à un contrôle préalable, sur le fondement d'un principe fondamental reconnu par les lois de la République.",u:["https://fr.wikipedia.org/wiki/D%C3%A9cision_Libert%C3%A9_d%27association"],s:"Banque administration"},
{id:"ad2-062",t:"admin",q:"Quel texte mentionne les « principes fondamentaux reconnus par les lois de la République » (PFRLR) ?",o:["La Déclaration des droits de l'homme et du citoyen de 1789","La Charte de l'environnement","Le Préambule de la Constitution de 1946","L'article 1er de la Constitution de 1958"],a:2,e:"Le Préambule de 1946 les « réaffirme solennellement » ; le Conseil constitutionnel en a reconnu une dizaine (liberté d'association, droits de la défense…).",u:["https://fr.wikipedia.org/wiki/Principes_fondamentaux_reconnus_par_les_lois_de_la_R%C3%A9publique"],s:"Banque administration"},
{id:"ad2-063",t:"admin",q:"Lequel de ces droits est proclamé par le Préambule de la Constitution de 1946 ?",o:["Le droit de grève","La présomption d'innocence","Le droit de propriété","La séparation des pouvoirs"],a:0,e:"Les trois autres figurent dans la Déclaration de 1789 (art. 9, 17 et 16).",u:["https://fr.wikipedia.org/wiki/Pr%C3%A9ambule_de_la_Constitution_du_27_octobre_1946"],s:"Banque administration"},
{id:"ad2-064",t:"admin",q:"Quel article de la Déclaration de 1789 dispose que « la Société a le droit de demander compte à tout Agent public de son administration » ?",o:["L'article 12","L'article 15","L'article 2","L'article 4"],a:1,e:"Il fonde l'obligation de rendre des comptes et le contrôle de la gestion publique.",u:["https://fr.wikipedia.org/wiki/D%C3%A9claration_des_droits_de_l%27homme_et_du_citoyen_de_1789"],s:"Banque administration"},
{id:"ad2-065",t:"admin",q:"Quel article de la Déclaration de 1789 fonde l'égal accès aux emplois publics, « selon leur capacité, et sans autre distinction que celle de leurs vertus et de leurs talents » ?",o:["L'article 1er","L'article 6","L'article 13","L'article 16"],a:1,e:"Il fonde le principe du recrutement des fonctionnaires par concours.",u:["https://fr.wikipedia.org/wiki/D%C3%A9claration_des_droits_de_l%27homme_et_du_citoyen_de_1789"],s:"Banque administration"},
{id:"ad2-066",t:"admin",q:"Quelle loi constitutionnelle a adossé la Charte de l'environnement à la Constitution ?",o:["La loi constitutionnelle du 23 juillet 2008","La loi constitutionnelle du 28 mars 2003","La loi constitutionnelle du 1er mars 2005","La loi constitutionnelle du 8 mars 2024"],a:2,e:"Le Préambule de la Constitution renvoie à la « Charte de l'environnement de 2004 », approuvée par le Congrès le 28 février 2005.",u:["https://fr.wikipedia.org/wiki/Charte_de_l%27environnement"],s:"Banque administration"},
{id:"ad2-067",t:"admin",q:"Quelle valeur le Conseil constitutionnel reconnaît-il à la lutte contre la fraude fiscale ?",o:["Celle d'un principe fondamental reconnu par les lois de la République","Celle d'un simple principe général du droit","Aucune valeur juridique particulière","Celle d'un objectif de valeur constitutionnelle"],a:3,e:"Décision du 29 décembre 1999 : cet objectif découle de l'article 13 de la Déclaration de 1789.",s:"Banque administration"},
{id:"ad2-068",t:"admin",q:"Depuis l'arrêt Duvignères (Conseil d'État, 2002), une circulaire peut faire l'objet d'un recours pour excès de pouvoir lorsque :",o:["elle présente un caractère impératif","elle a été publiée au Journal officiel","elle a été signée par un ministre","elle date de moins de deux mois"],a:0,e:"L'arrêt GISTI (2020) a élargi le recours aux documents de portée générale susceptibles d'avoir des effets notables.",u:["https://fr.wikipedia.org/wiki/Arr%C3%AAt_Duvign%C3%A8res"],s:"Banque administration"},
{id:"ad2-069",t:"admin",q:"Le Conseil constitutionnel accepte-t-il de contrôler une loi adoptée par référendum ?",o:["Oui, dans le mois qui suit le scrutin","Oui, mais seulement par la voie de la QPC","Oui, à la demande de soixante députés","Non : il s'y refuse depuis 1962, car elle est l'expression directe de la souveraineté nationale"],a:3,e:"Décision du 6 novembre 1962 sur la loi relative à l'élection du président de la République au suffrage universel direct.",s:"Banque administration"},
{id:"ad2-070",t:"admin",q:"Sauf disposition contraire, quand une loi publiée au Journal officiel entre-t-elle en vigueur ?",o:["Le jour de son vote définitif","Un mois après sa promulgation","Le lendemain de sa publication, sauf si son exécution nécessite des mesures d'application","Le 1er janvier qui suit sa publication"],a:2,e:"Article 1er du Code civil, dans sa rédaction issue de l'ordonnance du 20 février 2004.",s:"Banque administration"},
{id:"ad2-071",t:"admin",q:"Selon quelle procédure l'élection du président de la République au suffrage universel direct a-t-elle été adoptée en 1962 ?",o:["Un référendum fondé sur l'article 11","Une révision votée par le Congrès selon l'article 89","Une loi organique","Une ordonnance de l'article 38"],a:0,e:"Le recours à l'article 11 pour réviser la Constitution fut très contesté et provoqua le vote d'une motion de censure contre le gouvernement Pompidou.",u:["https://fr.wikipedia.org/wiki/Article_11_de_la_Constitution_de_la_Cinqui%C3%A8me_R%C3%A9publique_fran%C3%A7aise"],s:"Banque administration"},
{id:"ad2-072",t:"admin",q:"Avant décembre 2024, quel gouvernement fut le seul de la Ve République renversé par une motion de censure ?",o:["Le gouvernement Debré, en 1960","Le gouvernement Pompidou, en octobre 1962","Le gouvernement Rocard, en 1990","Le gouvernement Chirac, en 1987"],a:1,e:"Le général de Gaulle répondit en dissolvant l'Assemblée nationale.",u:["https://fr.wikipedia.org/wiki/Motion_de_censure"],s:"Banque administration"},
{id:"ad2-073",t:"admin",q:"Le 4 décembre 2024, l'adoption d'une motion de censure a renversé le gouvernement de :",o:["Gabriel Attal","Michel Barnier","Élisabeth Borne","François Bayrou"],a:1,e:"Motion déposée après le recours au 49.3 sur le projet de loi de financement de la sécurité sociale pour 2025 : deuxième censure adoptée sous la Ve République.",u:["https://fr.wikipedia.org/wiki/Gouvernement_Michel_Barnier"],s:"Banque administration"},
{id:"ad2-074",t:"admin",q:"Après l'échec du référendum du 27 avril 1969 sur la régionalisation et la réforme du Sénat, le général de Gaulle :",o:["a démissionné","a dissous l'Assemblée nationale","a recouru à l'article 16","a organisé un second référendum"],a:0,e:"Il quitte ses fonctions le 28 avril 1969.",u:["https://fr.wikipedia.org/wiki/R%C3%A9f%C3%A9rendum_constitutionnel_fran%C3%A7ais_de_1969"],s:"Banque administration"},
{id:"ad2-075",t:"admin",q:"Lors du référendum du 29 mai 2005, les Français ont rejeté :",o:["le traité de Maastricht","le quinquennat","le traité établissant une Constitution pour l'Europe","l'élargissement de la CEE au Royaume-Uni"],a:2,e:"Le « non » l'emporta avec environ 55 % des suffrages ; Maastricht (1992), le quinquennat (2000) et l'élargissement (1972) avaient été approuvés.",s:"Banque administration"},
{id:"ad2-076",t:"admin",q:"Qui a assuré à deux reprises, en 1969 et en 1974, l'intérim de la présidence de la République ?",o:["Gaston Monnerville","Jacques Chaban-Delmas","Edgar Faure","Alain Poher"],a:3,e:"En sa qualité de président du Sénat (art. 7), après la démission du général de Gaulle puis le décès de Georges Pompidou.",u:["https://fr.wikipedia.org/wiki/Alain_Poher"],s:"Banque administration"},
{id:"ad2-077",t:"admin",q:"Entre 1958 et 2002, combien de cohabitations la Ve République a-t-elle connues ?",o:["Deux","Quatre","Trois","Une"],a:2,e:"1986-1988 (Mitterrand-Chirac), 1993-1995 (Mitterrand-Balladur) et 1997-2002 (Chirac-Jospin).",u:["https://fr.wikipedia.org/wiki/Cohabitation_(politique)"],s:"Banque administration"},
{id:"ad2-078",t:"admin",q:"Quelle a été la plus longue cohabitation de la Ve République ?",o:["Jacques Chirac et Lionel Jospin (1997-2002)","François Mitterrand et Jacques Chirac (1986-1988)","François Mitterrand et Édouard Balladur (1993-1995)","Valéry Giscard d'Estaing et Jacques Chirac (1974-1976)"],a:0,e:"Elle est née de la dissolution décidée par Jacques Chirac en 1997 ; Giscard d'Estaing et Chirac appartenaient à la même majorité.",u:["https://fr.wikipedia.org/wiki/Cohabitation_(politique)"],s:"Banque administration"},
{id:"ad2-079",t:"admin",q:"Lors de la première cohabitation, en 1986, le président Mitterrand a refusé de signer :",o:["la nomination de Jacques Chirac comme Premier ministre","des ordonnances, notamment sur les privatisations","la loi de finances pour 1987","la dissolution demandée par le Premier ministre"],a:1,e:"Le Gouvernement a dû faire adopter ces mesures par la voie législative ordinaire.",u:["https://fr.wikipedia.org/wiki/Cohabitation_(politique)"],s:"Banque administration"},
{id:"ad2-080",t:"admin",q:"Qui fut le premier Premier ministre de la Ve République ?",o:["Georges Pompidou","Jacques Chaban-Delmas","Maurice Couve de Murville","Michel Debré"],a:3,e:"De janvier 1959 à avril 1962 ; il fut l'un des principaux rédacteurs de la Constitution.",u:["https://fr.wikipedia.org/wiki/Michel_Debr%C3%A9"],s:"Banque administration"},
{id:"ad2-081",t:"admin",q:"Qui est devenu en janvier 2024, à 34 ans, le plus jeune Premier ministre de la Ve République ?",o:["Laurent Fabius","Jordan Bardella","Sébastien Lecornu","Gabriel Attal"],a:3,e:"Il a battu le record de Laurent Fabius, nommé à 37 ans en 1984.",u:["https://fr.wikipedia.org/wiki/Gabriel_Attal"],s:"Banque administration"},
{id:"ad2-082",t:"admin",q:"Quelle révision constitutionnelle a créé la Cour de justice de la République ?",o:["La révision du 27 juillet 1993","La révision du 4 août 1995","La révision du 23 février 2007","La révision du 23 juillet 2008"],a:0,e:"Créée après l'affaire du sang contaminé, elle a remplacé la Haute Cour de justice pour juger les ministres.",u:["https://fr.wikipedia.org/wiki/Cour_de_justice_de_la_R%C3%A9publique"],s:"Banque administration"},
{id:"ad2-083",t:"admin",q:"Laquelle de ces innovations est issue de la révision constitutionnelle du 23 juillet 2008 ?",o:["Le quinquennat","La Cour de justice de la République","La question prioritaire de constitutionnalité","Les lois de financement de la sécurité sociale"],a:2,e:"La révision de 2008 a aussi créé le Défenseur des droits et l'ordre du jour partagé ; les trois autres réformes datent de 2000, 1993 et 1996.",u:["https://fr.wikipedia.org/wiki/Question_prioritaire_de_constitutionnalit%C3%A9"],s:"Banque administration"},
{id:"ad2-084",t:"admin",q:"Combien de présentations (« parrainages ») d'élus un candidat à l'élection présidentielle doit-il recueillir ?",o:["100","500","1 000","5 000"],a:1,e:"Elles doivent provenir d'au moins 30 départements ou collectivités d'outre-mer, sans que plus d'un dixième viennent d'un même département.",s:"Banque administration"},
{id:"ad2-085",t:"admin",q:"Comment appelle-t-on un décret pris dans une matière relevant de l'article 37, sans loi préalable ?",o:["Un décret d'application","Une ordonnance","Une loi du pays","Un règlement autonome"],a:3,e:"Les décrets d'application précisent, eux, les modalités d'exécution d'une loi (art. 21).",u:["https://fr.wikipedia.org/wiki/Article_37_de_la_Constitution_de_la_Cinqui%C3%A8me_R%C3%A9publique_fran%C3%A7aise"],s:"Banque administration"},
{id:"ad2-086",t:"admin",q:"Selon l'arrêt Jamart (Conseil d'État, 1936), un ministre dispose d'un pouvoir réglementaire :",o:["général, dans tous les domaines de son ministère","en tant que chef de service, pour l'organisation de son service","uniquement par délégation du président de la République","uniquement en période de crise"],a:1,e:"Les ministres n'ont pas de pouvoir réglementaire général, réservé au Premier ministre (art. 21).",s:"Banque administration"},
{id:"ad2-087",t:"admin",q:"Quel arrêt du Conseil d'État de 1919 reconnaît au chef de l'exécutif un pouvoir de police générale, même sans texte ?",o:["Labonne","Benjamin","Blanco","Jamart"],a:0,e:"Ce pouvoir appartient aujourd'hui au Premier ministre ; le maire et le préfet exercent la police administrative à l'échelon local.",s:"Banque administration"},
{id:"ad2-088",t:"admin",q:"Auprès de qui est placé le Secrétariat général du Gouvernement (SGG) ?",o:["Auprès du président de la République","Auprès du ministre de l'Intérieur","Auprès du Premier ministre","Auprès du vice-président du Conseil d'État"],a:2,e:"Il organise le travail gouvernemental, veille à la qualité juridique des textes et à leur publication au Journal officiel.",u:["https://fr.wikipedia.org/wiki/Secr%C3%A9tariat_g%C3%A9n%C3%A9ral_du_Gouvernement_(France)"],s:"Banque administration"},
{id:"ad2-089",t:"admin",q:"Quelle direction publie le Journal officiel et édite Légifrance, service-public.fr et vie-publique.fr ?",o:["La direction de l'information légale et administrative (DILA)","La direction interministérielle du numérique (DINUM)","Le service d'information du Gouvernement (SIG)","L'Imprimerie nationale"],a:0,e:"Elle relève des services du Premier ministre.",u:["https://fr.wikipedia.org/wiki/Direction_de_l%27information_l%C3%A9gale_et_administrative"],s:"Banque administration"},
{id:"ad2-090",t:"admin",q:"Qui constitue l'essentiel du collège électoral des sénateurs ?",o:["Les conseillers régionaux","Les députés","Les délégués des conseils municipaux","Les conseillers départementaux"],a:2,e:"Environ 95 % des grands électeurs sont des délégués des conseils municipaux, ce qui explique le poids des communes rurales au Sénat.",u:["https://fr.wikipedia.org/wiki/%C3%89lections_s%C3%A9natoriales_en_France"],s:"Banque administration"},
{id:"ad2-091",t:"admin",q:"Combien de députés faut-il au minimum pour constituer un groupe politique à l'Assemblée nationale ?",o:["10","15","20","30"],a:1,e:"Seuil abaissé de 20 à 15 en 2009 ; il est de 10 au Sénat.",s:"Banque administration"},
{id:"ad2-092",t:"admin",q:"Le 11 décembre 2023, comment le projet de loi « immigration » a-t-il été rejeté d'emblée par l'Assemblée nationale ?",o:["Par une motion de censure","Par l'irrecevabilité de l'article 40","Par une décision du Conseil constitutionnel","Par l'adoption d'une motion de rejet préalable"],a:3,e:"L'adoption de cette motion entraîne le rejet du texte sans examen des articles ; le Gouvernement a ensuite réuni une commission mixte paritaire.",s:"Banque administration"},
{id:"ad2-093",t:"admin",q:"Où se réunit le Parlement convoqué en Congrès ?",o:["Au Palais-Bourbon","Au palais du Luxembourg","Au château de Versailles","Au palais de l'Élysée"],a:2,e:"Le Congrès réunit les députés et les sénateurs, notamment pour approuver un projet de révision constitutionnelle (majorité des 3/5).",s:"Banque administration"},
{id:"ad2-094",t:"admin",q:"Un parlementaire peut-il recevoir plusieurs délégations de vote ?",o:["Oui, sans limite","Non : nul ne peut recevoir délégation de plus d'un mandat","Oui, jusqu'à trois","Oui, si son groupe l'y autorise"],a:1,e:"Art. 27 : le droit de vote des parlementaires est personnel et la délégation n'est autorisée qu'exceptionnellement.",u:["https://www.conseil-constitutionnel.fr/le-bloc-de-constitutionnalite/texte-integral-de-la-constitution-du-4-octobre-1958-en-vigueur"],s:"Constitution, art. 27"},
{id:"ad2-095",t:"admin",q:"Quelle juridiction est née, le 1er janvier 2020, de la fusion des tribunaux d'instance et de grande instance ?",o:["Le tribunal judiciaire","Le tribunal de police","Le tribunal correctionnel","Le tribunal des activités économiques"],a:0,e:"Réforme issue de la loi de programmation et de réforme pour la justice du 23 mars 2019.",u:["https://fr.wikipedia.org/wiki/Tribunal_judiciaire_(France)"],s:"Banque administration"},
{id:"ad2-096",t:"admin",q:"Que juge la Cour de cassation ?",o:["Les faits et le droit, comme un troisième degré de juridiction","Uniquement les affaires pénales les plus graves","Les recours contre les décrets","Le droit : elle vérifie l'application des règles de droit, sans rejuger les faits"],a:3,e:"Elle peut casser une décision et renvoyer l'affaire devant une juridiction du même degré.",u:["https://fr.wikipedia.org/wiki/Cour_de_cassation_(France)"],s:"Banque administration"},
{id:"ad2-097",t:"admin",q:"Quelles juridictions, sans jury populaire, ont été généralisées le 1er janvier 2023 pour juger en première instance, hors récidive, les crimes punis de 15 ou 20 ans de réclusion commis par des majeurs ?",o:["Les cours criminelles départementales","Les cours d'assises","Les tribunaux correctionnels","Les chambres de l'instruction"],a:0,e:"Lors de leur généralisation, elles étaient composées de cinq magistrats, sans jurés ; la cour d'assises, avec jury, restait compétente pour les crimes punis de 30 ans de réclusion ou plus, en cas de récidive et en appel.",u:["https://fr.wikipedia.org/wiki/Cour_criminelle_d%C3%A9partementale"],s:"Banque administration"},
{id:"ad2-098",t:"admin",q:"Depuis la loi du 25 juillet 2013, le garde des Sceaux peut-il adresser aux magistrats du parquet des instructions dans des affaires individuelles ?",o:["Oui, par écrit et versées au dossier","Non, il ne peut adresser que des instructions générales de politique pénale","Oui, mais seulement oralement","Oui, avec l'accord du CSM"],a:1,e:"Les magistrats du parquet restent placés sous son autorité, mais les instructions individuelles sont interdites.",s:"Banque administration"},
{id:"ad2-099",t:"admin",q:"Selon l'article 40 du code de procédure pénale, que doit faire un fonctionnaire qui, dans l'exercice de ses fonctions, acquiert la connaissance d'un crime ou d'un délit ?",o:["En informer uniquement son supérieur hiérarchique","Saisir le Défenseur des droits","En donner avis sans délai au procureur de la République","Attendre l'autorisation écrite de son ministre"],a:2,e:"Il transmet au procureur tous les renseignements, procès-verbaux et actes qui y sont relatifs.",s:"Banque administration"},
{id:"ad2-100",t:"admin",q:"Quel parquet à compétence nationale, créé par la loi du 6 décembre 2013, traite les affaires complexes de fraude fiscale et d'atteintes à la probité ?",o:["Le parquet national antiterroriste (PNAT)","Le parquet européen","Le parquet général près la Cour des comptes","Le parquet national financier (PNF)"],a:3,e:"Installé le 1er février 2014 à Paris, après l'affaire Cahuzac.",u:["https://fr.wikipedia.org/wiki/Parquet_national_financier"],s:"Banque administration"},
{id:"ad2-101",t:"admin",q:"Quelle autorité présidait le Tribunal des conflits jusqu'à la réforme du 16 février 2015 ?",o:["Le garde des Sceaux, ministre de la Justice","Le président de la République","Le vice-président du Conseil d'État","Le premier président de la Cour de cassation"],a:0,e:"La réforme a mis fin à ce rôle, critiqué au nom de la séparation des pouvoirs ; le Tribunal est désormais présidé par l'un de ses membres.",u:["https://fr.wikipedia.org/wiki/Tribunal_des_conflits_(France)"],s:"Banque administration"},
{id:"ad2-102",t:"admin",q:"Quelle juridiction a rendu l'arrêt Blanco (1873), qui fonde la responsabilité de l'administration et la compétence du juge administratif ?",o:["Le Conseil d'État","La Cour de cassation","Le Conseil constitutionnel","Le Tribunal des conflits"],a:3,e:"L'arrêt affirme que la responsabilité de l'État n'est « ni générale ni absolue » et obéit à des règles spéciales.",u:["https://fr.wikipedia.org/wiki/Arr%C3%AAt_Blanco"],s:"Banque administration"},
{id:"ad2-103",t:"admin",q:"Quel arrêt du Conseil d'État de 1889 met fin à la théorie du « ministre-juge » ?",o:["Blanco","Cadot","Nicolo","Labonne"],a:1,e:"Le Conseil d'État devient juge de droit commun du contentieux administratif ; il rendait la justice déléguée depuis la loi du 24 mai 1872.",u:["https://fr.wikipedia.org/wiki/Arr%C3%AAt_Cadot"],s:"Banque administration"},
{id:"ad2-104",t:"admin",q:"Qui assure effectivement la présidence du Conseil d'État ?",o:["Le garde des Sceaux","Le président de la section du contentieux","Le vice-président du Conseil d'État","Le premier président de la Cour des comptes"],a:2,e:"Le vice-président dirige l'institution et préside ses principales formations, consultatives comme contentieuses.",u:["https://fr.wikipedia.org/wiki/Conseil_d%27%C3%89tat_(France)"],s:"Banque administration"},
{id:"ad2-105",t:"admin",q:"L'avis du Conseil d'État sur un projet de loi est :",o:["facultatif","obligatoire et contraignant","rendu après le vote du Parlement","obligatoire, mais il ne lie pas le Gouvernement"],a:3,e:"Art. 39 : le Gouvernement peut passer outre ; depuis 2015, le Gouvernement rend souvent ces avis publics.",u:["https://fr.wikipedia.org/wiki/Article_39_de_la_Constitution_de_la_Cinqui%C3%A8me_R%C3%A9publique_fran%C3%A7aise"],s:"Banque administration"},
{id:"ad2-106",t:"admin",q:"Quelle juridiction est juge de cassation des arrêts de la Cour des comptes ?",o:["Le Conseil d'État","La Cour de cassation","Le Conseil constitutionnel","Le Tribunal des conflits"],a:0,e:"Les juridictions financières appartiennent à l'ordre administratif.",u:["https://fr.wikipedia.org/wiki/Conseil_d%27%C3%89tat_(France)"],s:"Banque administration"},
{id:"ad2-107",t:"admin",q:"Qui assure la gestion des tribunaux administratifs et des cours administratives d'appel ?",o:["Le ministère de la Justice","Le Conseil d'État","Le ministère de l'Intérieur","Les préfectures de région"],a:1,e:"Le secrétariat général du Conseil d'État gère leurs moyens et leurs personnels, ce qui garantit l'indépendance de la juridiction administrative.",u:["https://fr.wikipedia.org/wiki/Cour_administrative_d%27appel"],s:"Banque administration"},
{id:"ad2-108",t:"admin",q:"Depuis 2009, comment s'appelle le membre de la juridiction administrative qui expose publiquement, en toute indépendance, son opinion sur la solution du litige ?",o:["Le commissaire du Gouvernement","L'avocat général","Le rapporteur public","Le procureur de la République"],a:2,e:"Il s'appelait auparavant « commissaire du Gouvernement », bien qu'il ne représente pas le Gouvernement.",u:["https://fr.wikipedia.org/wiki/Rapporteur_public"],s:"Banque administration"},
{id:"ad2-109",t:"admin",q:"Selon la jurisprudence Czabaj (Conseil d'État, 2016), une décision individuelle notifiée sans mention des voies et délais de recours ne peut plus être contestée au-delà d'un délai raisonnable, en principe de :",o:["deux mois","cinq ans","un an","trente ans"],a:2,e:"Ce délai court à compter de la notification de la décision ou de la date à laquelle l'intéressé en a eu connaissance.",s:"Banque administration"},
{id:"ad2-110",t:"admin",q:"Dans quel délai le juge du référé-liberté se prononce-t-il ?",o:["48 heures","8 jours","Un mois","Deux mois"],a:0,e:"Il faut une urgence et une atteinte grave et manifestement illégale à une liberté fondamentale (art. L. 521-2 du code de justice administrative).",u:["https://fr.wikipedia.org/wiki/R%C3%A9f%C3%A9r%C3%A9-libert%C3%A9_en_droit_administratif_fran%C3%A7ais"],s:"Banque administration"},
{id:"ad2-111",t:"admin",q:"Laquelle de ces juridictions relève de l'ordre administratif ?",o:["Le conseil de prud'hommes","La Cour nationale du droit d'asile","Le tribunal de commerce","La cour d'assises"],a:1,e:"Elle juge les recours contre les décisions de l'OFPRA, sous le contrôle de cassation du Conseil d'État.",s:"Banque administration"},
{id:"ad2-112",t:"admin",q:"Depuis la loi du 12 novembre 2013, que vaut en principe le silence gardé pendant deux mois par l'administration sur une demande ?",o:["Une décision de rejet","Une absence de décision, sans effet","Une demande de pièces complémentaires","Une décision d'acceptation"],a:3,e:"Le principe « silence vaut acceptation » connaît de nombreuses exceptions, notamment pour les demandes à caractère financier.",s:"Banque administration"},
{id:"ad2-113",t:"admin",q:"Entre 1982 et 1988, quel titre portaient les préfets ?",o:["Intendants","Commissaires de la République","Représentants du peuple","Délégués du Gouvernement"],a:1,e:"La loi du 2 mars 1982 a confié l'exécutif départemental au président du conseil général ; le titre de préfet a été rétabli en 1988.",u:["https://fr.wikipedia.org/wiki/Pr%C3%A9fet_(France)"],s:"Banque administration"},
{id:"ad2-114",t:"admin",q:"Comment les préfets sont-ils nommés ?",o:["Par arrêté du ministre de l'Intérieur","Par élection au sein du conseil départemental","Par le Premier ministre, à l'issue d'un concours","Par décret du président de la République en Conseil des ministres"],a:3,e:"Art. 13 de la Constitution : ce sont des emplois à la décision du Gouvernement.",u:["https://fr.wikipedia.org/wiki/Pr%C3%A9fet_(France)"],s:"Banque administration"},
{id:"ad2-115",t:"admin",q:"Le préfet de région est aussi :",o:["le président du conseil régional","le préfet de zone de défense de toutes les régions","le préfet du département où se trouve le chef-lieu de la région","le directeur régional des finances publiques"],a:2,e:"Depuis 2010, il a autorité sur les préfets de département, sauf dans certaines matières (contrôle de légalité, ordre public…).",u:["https://fr.wikipedia.org/wiki/Pr%C3%A9fet_(France)"],s:"Banque administration"},
{id:"ad2-116",t:"admin",q:"Depuis la réforme de 2010, quel échelon est le niveau de droit commun du pilotage des politiques publiques de l'État sur le territoire ?",o:["La région","Le département","L'arrondissement","La commune"],a:0,e:"Le département reste l'échelon de mise en œuvre ; le préfet de région a autorité sur les préfets de département (décret du 16 février 2010).",s:"Banque administration"},
{id:"ad2-117",t:"admin",q:"Laquelle de ces directions est une direction départementale interministérielle (DDI) placée sous l'autorité du préfet ?",o:["La direction départementale des finances publiques (DDFiP)","La direction des services départementaux de l'Éducation nationale","La direction départementale des territoires (DDT)","Le groupement de gendarmerie départementale"],a:2,e:"Les DDI existent depuis le 1er janvier 2010 ; la DGFiP, l'Éducation nationale et la gendarmerie disposent de leurs propres réseaux.",u:["https://fr.wikipedia.org/wiki/Direction_d%C3%A9partementale_interminist%C3%A9rielle"],s:"Banque administration"},
{id:"ad2-118",t:"admin",q:"Dans quel cadre les directions départementales interministérielles (DDI) ont-elles été créées en 2010 ?",o:["La loi NOTRe","La loi 3DS","Le programme Action publique 2022","La réforme de l'administration territoriale de l'État (RéATE), volet de la RGPP"],a:3,e:"Elles regroupent des services auparavant dispersés entre plusieurs ministères (équipement, agriculture, cohésion sociale…).",u:["https://fr.wikipedia.org/wiki/Direction_d%C3%A9partementale_interminist%C3%A9rielle"],s:"Banque administration"},
{id:"ad2-119",t:"admin",q:"Quelle direction régionale, créée le 1er avril 2021, regroupe les services de l'économie, de l'emploi, du travail et des solidarités ?",o:["La DREAL","La DREETS","La DRAAF","La DRAC"],a:1,e:"Elle a repris les missions des anciennes DIRECCTE et des services régionaux de la cohésion sociale.",u:["https://fr.wikipedia.org/wiki/Direction_r%C3%A9gionale_de_l%27%C3%89conomie,_de_l%27Emploi,_du_Travail_et_des_Solidarit%C3%A9s"],s:"Banque administration"},
{id:"ad2-120",t:"admin",q:"Lequel de ces principes ne fait pas partie des « lois de Rolland » applicables au service public ?",o:["La gratuité","La continuité","L'égalité","La mutabilité (adaptabilité)"],a:0,e:"Le service public n'est pas nécessairement gratuit ; les trois principes classiques sont la continuité, l'égalité et la mutabilité.",s:"Banque administration"},
{id:"ad2-121",t:"admin",q:"Dans le réseau de la DGFiP, le directeur régional des finances publiques (DRFiP) est aussi :",o:["le préfet de région","le président de la chambre régionale des comptes","le directeur départemental des finances publiques du département chef-lieu de la région","le directeur des vérifications nationales et internationales"],a:2,e:"Les autres départements sont dirigés par un directeur départemental des finances publiques (DDFiP).",u:["https://fr.wikipedia.org/wiki/Direction_g%C3%A9n%C3%A9rale_des_Finances_publiques"],s:"Banque administration"},
{id:"ad2-122",t:"admin",q:"Qu'est-ce qui caractérise une autorité administrative indépendante (AAI) ?",o:["Elle dispose toujours de la personnalité morale","Elle agit au nom de l'État sans être soumise au pouvoir hiérarchique du Gouvernement","Ses membres sont élus au suffrage universel","Ses décisions échappent au contrôle du juge"],a:1,e:"Les AAI dotées de la personnalité morale sont des autorités publiques indépendantes (API) ; toutes restent soumises au contrôle du juge.",s:"Banque administration"},
{id:"ad2-123",t:"admin",q:"Quel est le statut juridique de la CNIL ?",o:["Une autorité publique indépendante, dotée de la personnalité morale","Un établissement public administratif","Une direction du ministère de la Justice","Une autorité administrative indépendante, sans personnalité morale"],a:3,e:"Créée par la loi Informatique et libertés du 6 janvier 1978. Les autorités publiques indépendantes (AMF, Arcom, HAS…) ont, elles, la personnalité morale.",u:["https://fr.wikipedia.org/wiki/Commission_nationale_de_l%27informatique_et_des_libert%C3%A9s"],s:"Banque administration"},
{id:"ad2-124",t:"admin",q:"Quelle autorité, créée par la loi du 11 octobre 2013 après l'affaire Cahuzac, contrôle les déclarations de patrimoine et d'intérêts des responsables publics ?",o:["La Haute Autorité pour la transparence de la vie publique (HATVP)","La Commission nationale des comptes de campagne et des financements politiques","L'Agence française anticorruption","La Cour de discipline budgétaire et financière"],a:0,e:"Elle publie notamment les déclarations d'intérêts des ministres et des parlementaires.",u:["https://fr.wikipedia.org/wiki/Haute_Autorit%C3%A9_pour_la_transparence_de_la_vie_publique"],s:"Banque administration"},
{id:"ad2-125",t:"admin",q:"Quelle autorité a repris en 2020 les missions de la commission de déontologie de la fonction publique ?",o:["La Cour des comptes","La HATVP","Le Défenseur des droits","La CNIL"],a:1,e:"Transfert opéré par la loi du 6 août 2019 ; la HATVP contrôle notamment les départs vers le privé des agents occupant les emplois les plus exposés.",u:["https://fr.wikipedia.org/wiki/Haute_Autorit%C3%A9_pour_la_transparence_de_la_vie_publique"],s:"Banque administration"},
{id:"ad2-126",t:"admin",q:"De quelle fusion est née en 2003 l'Autorité des marchés financiers (AMF) ?",o:["De la Banque de France et de la Commission bancaire","Du CSA et de l'Hadopi","Du Conseil de la concurrence et de la DGCCRF","De la Commission des opérations de bourse, du Conseil des marchés financiers et du Conseil de discipline de la gestion financière"],a:3,e:"Loi de sécurité financière du 1er août 2003 ; l'AMF est une autorité publique indépendante.",u:["https://fr.wikipedia.org/wiki/Autorit%C3%A9_des_march%C3%A9s_financiers_(France)"],s:"Banque administration"},
{id:"ad2-127",t:"admin",q:"Quels secteurs l'Arcep régule-t-elle ?",o:["L'audiovisuel et le numérique","L'électricité et le gaz","Les communications électroniques, les postes et la distribution de la presse","Les transports ferroviaires et routiers"],a:2,e:"L'audiovisuel relève de l'Arcom, l'énergie de la CRE et les transports de l'Autorité de régulation des transports.",u:["https://fr.wikipedia.org/wiki/Autorit%C3%A9_de_r%C3%A9gulation_des_communications_%C3%A9lectroniques,_des_postes_et_de_la_distribution_de_la_presse"],s:"Banque administration"},
{id:"ad2-128",t:"admin",q:"À quel organisme l'Autorité de la concurrence a-t-elle succédé en 2009 ?",o:["Au Conseil de la concurrence","À la DGCCRF","À la Commission des opérations de bourse","À l'Arcep"],a:0,e:"Créée par la loi de modernisation de l'économie du 4 août 2008, elle contrôle aussi les concentrations.",u:["https://fr.wikipedia.org/wiki/Autorit%C3%A9_de_la_concurrence_(France)"],s:"Banque administration"},
{id:"ad2-129",t:"admin",q:"Devant quelle juridiction les décisions de l'Autorité de la concurrence relatives aux pratiques anticoncurrentielles sont-elles contestées ?",o:["Le Conseil d'État","Le tribunal administratif de Paris","La cour d'appel de Paris","Le Conseil constitutionnel"],a:2,e:"Ses décisions en matière de concentrations relèvent, elles, du Conseil d'État.",u:["https://fr.wikipedia.org/wiki/Autorit%C3%A9_de_la_concurrence_(France)"],s:"Banque administration"},
{id:"ad2-130",t:"admin",q:"En janvier 2025, l'Autorité de sûreté nucléaire (ASN) a fusionné avec l'Institut de radioprotection et de sûreté nucléaire (IRSN) pour former :",o:["la Commission de régulation de l'énergie","le Commissariat à l'énergie atomique","l'Agence de l'environnement et de la maîtrise de l'énergie","l'Autorité de sûreté nucléaire et de radioprotection (ASNR)"],a:3,e:"Fusion prévue par la loi du 21 mai 2024 sur la gouvernance de la sûreté nucléaire et de la radioprotection.",u:["https://fr.wikipedia.org/wiki/Autorit%C3%A9_de_s%C3%BBret%C3%A9_nucl%C3%A9aire_(France)"],s:"Banque administration"},
{id:"ad2-131",t:"admin",q:"Avant de saisir le juge d'un refus de communication d'un document administratif, que doit faire l'usager ?",o:["Saisir obligatoirement la CADA pour avis","Saisir le Défenseur des droits","Poser une question prioritaire de constitutionnalité","Saisir directement le Conseil d'État"],a:0,e:"La Commission d'accès aux documents administratifs, créée en 1978, rend un avis qui ne lie pas l'administration.",u:["https://fr.wikipedia.org/wiki/Commission_d%27acc%C3%A8s_aux_documents_administratifs"],s:"Banque administration"},
{id:"ad2-132",t:"admin",q:"Quelle autorité indépendante contrôle les conditions de prise en charge des personnes privées de liberté (prisons, centres de rétention, hôpitaux psychiatriques) ?",o:["Le Défenseur des droits","Le Contrôleur général des lieux de privation de liberté","La Commission nationale consultative des droits de l'homme","Le Conseil supérieur de la magistrature"],a:1,e:"Institué par la loi du 30 octobre 2007.",u:["https://fr.wikipedia.org/wiki/Contr%C3%B4leur_g%C3%A9n%C3%A9ral_des_lieux_de_privation_de_libert%C3%A9"],s:"Banque administration"},
{id:"ad2-133",t:"admin",q:"Quelle autorité contrôle les comptes de campagne des candidats aux élections ?",o:["La Commission nationale des comptes de campagne et des financements politiques (CNCCFP)","La Cour des comptes","La HATVP","Le Conseil d'État"],a:0,e:"Elle peut saisir le juge de l'élection ; un candidat dont le compte est rejeté n'est pas remboursé de ses dépenses.",u:["https://fr.wikipedia.org/wiki/Commission_nationale_des_comptes_de_campagne_et_des_financements_politiques"],s:"Banque administration"},
{id:"ad2-134",t:"admin",q:"Quel est le statut de l'Agence française anticorruption (AFA), créée par la loi Sapin 2 de 2016 ?",o:["Une autorité administrative indépendante","Une juridiction spécialisée","Un établissement public industriel et commercial","Un service à compétence nationale placé auprès des ministres de la Justice et du Budget"],a:3,e:"Elle contrôle notamment les dispositifs anticorruption des grandes entreprises et des acteurs publics.",u:["https://fr.wikipedia.org/wiki/Agence_fran%C3%A7aise_anticorruption"],s:"Banque administration"},
{id:"ad2-135",t:"admin",q:"Outre les comptes de l'État, quels comptes la Cour des comptes certifie-t-elle chaque année ?",o:["Ceux de toutes les entreprises cotées","Ceux des partis politiques","Ceux du régime général de la sécurité sociale","Ceux des communes de plus de 3 500 habitants"],a:2,e:"Cette certification s'inscrit dans sa mission d'assistance au Parlement et au Gouvernement (art. 47-2 de la Constitution).",u:["https://fr.wikipedia.org/wiki/Cour_des_comptes_(France)"],s:"Banque administration"},
{id:"ad2-136",t:"admin",q:"Quelle garantie d'indépendance les magistrats de la Cour des comptes possèdent-ils ?",o:["L'élection par les parlementaires","L'inamovibilité","Un droit de veto sur les lois de finances","L'immunité pénale"],a:1,e:"Elle est prévue par le code des juridictions financières.",u:["https://fr.wikipedia.org/wiki/Cour_des_comptes_(France)"],s:"Banque administration"},
{id:"ad2-137",t:"admin",q:"Comment s'appelle le rapport dans lequel la Cour des comptes présente chaque année ses principales observations ?",o:["Le rapport annuel de performances","Le rapport économique, social et financier","Le rapport public annuel","Le « jaune » budgétaire"],a:2,e:"Les rapports annuels de performances sont, eux, produits par les ministères et annexés à la loi relative aux résultats de la gestion.",u:["https://fr.wikipedia.org/wiki/Cour_des_comptes_(France)"],s:"Banque administration"},
{id:"ad2-138",t:"admin",q:"Sous l'autorité de qui l'Inspection générale des finances (IGF) est-elle placée ?",o:["Des ministres chargés de l'économie et du budget","Du premier président de la Cour des comptes","Du président de la commission des finances de l'Assemblée nationale","Du gouverneur de la Banque de France"],a:0,e:"Elle contrôle et audite les services et les politiques publiques, souvent dans un cadre interministériel.",u:["https://fr.wikipedia.org/wiki/Inspection_g%C3%A9n%C3%A9rale_des_finances_(France)"],s:"Banque administration"},
{id:"ad2-139",t:"admin",q:"De quel ministère relève l'Inspection générale de l'administration (IGA) ?",o:["Du ministère de l'Économie et des Finances","Des services du Premier ministre","Du ministère de la Justice","Du ministère de l'Intérieur"],a:3,e:"Elle contrôle notamment les préfectures et les services placés sous l'autorité du ministre de l'Intérieur.",u:["https://fr.wikipedia.org/wiki/Inspection_g%C3%A9n%C3%A9rale_de_l%27administration"],s:"Banque administration"},
{id:"ad2-140",t:"admin",q:"Quelle loi a créé les chambres régionales des comptes ?",o:["La loi du 16 septembre 1807","La loi du 2 mars 1982","La loi NOTRe du 7 août 2015","La LOLF du 1er août 2001"],a:1,e:"Leur création accompagne la suppression de la tutelle administrative a priori sur les collectivités territoriales.",u:["https://fr.wikipedia.org/wiki/Chambre_r%C3%A9gionale_des_comptes"],s:"Banque administration"},
{id:"ad2-141",t:"admin",q:"Comment s'appelait le comité d'experts chargé en 2017-2018 de proposer des réformes dans le cadre du programme Action publique 2022 ?",o:["Le comité Balladur","La commission Attali","CAP 22","La commission Pochard"],a:2,e:"Le comité Action publique 2022 a remis son rapport en 2018. Les autres comités ont travaillé sur les collectivités (Balladur), la croissance (Attali) et la fonction publique (Pochard).",s:"Banque administration"},
{id:"ad2-142",t:"admin",q:"Que signifie l'acronyme de la loi ESSOC du 10 août 2018 ?",o:["Égalité et solidarité des services ouverts aux citoyens","État au service d'une société de confiance","Engagement pour la simplification et l'organisation des collectivités","État simplifié, sobre, ouvert et connecté"],a:1,e:"Elle vise à simplifier les relations entre l'administration et les usagers de bonne foi.",u:["https://fr.wikipedia.org/wiki/Loi_pour_un_%C3%89tat_au_service_d%27une_soci%C3%A9t%C3%A9_de_confiance"],s:"Banque administration"},
{id:"ad2-143",t:"admin",q:"Outre le droit à l'erreur, quel droit la loi ESSOC a-t-elle créé pour les usagers ?",o:["Le droit au contrôle, qui permet de demander à l'administration de contrôler sa situation","Le droit à un fonctionnaire référent unique","Le droit à la suppression de toute sanction fiscale","Le droit de refuser une vérification de comptabilité"],a:0,e:"Les conclusions expresses d'un tel contrôle sont opposables à l'administration.",u:["https://fr.wikipedia.org/wiki/Loi_pour_un_%C3%89tat_au_service_d%27une_soci%C3%A9t%C3%A9_de_confiance"],s:"Banque administration"},
{id:"ad2-144",t:"admin",q:"Quelle direction interministérielle, créée en novembre 2017, pilote les programmes de transformation de l'action publique ?",o:["La direction générale de l'administration et de la fonction publique (DGAFP)","La direction interministérielle du numérique (DINUM)","La direction de l'information légale et administrative (DILA)","La direction interministérielle de la transformation publique (DITP)"],a:3,e:"Elle a succédé au secrétariat général pour la modernisation de l'action publique (SGMAP).",u:["https://fr.wikipedia.org/wiki/Direction_interminist%C3%A9rielle_de_la_Transformation_publique"],s:"Banque administration"},
{id:"ad2-146",t:"admin",q:"Où est implanté le siège de l'Institut national du service public (INSP), qui a remplacé l'ENA ?",o:["Paris","Strasbourg","Lyon","Bordeaux"],a:1,e:"L'ENA s'y était installée à partir de 1991.",u:["https://fr.wikipedia.org/wiki/Institut_national_du_service_public"],s:"Banque administration"},
{id:"ad2-147",t:"admin",q:"Quel corps, créé le 1er janvier 2022, accueille la plupart des élèves sortant de l'INSP ?",o:["Le corps des administrateurs civils","Le corps des inspecteurs des finances publiques","Le corps des administrateurs de l'État","Le corps des attachés d'administration de l'État"],a:2,e:"Il est issu de la fusion des administrateurs civils et des conseillers économiques ; plusieurs grands corps (préfets, inspections…) ont été mis en extinction en 2023.",u:["https://fr.wikipedia.org/wiki/Administrateur_de_l%27%C3%89tat"],s:"Banque administration"},
{id:"ad2-148",t:"admin",q:"Combien y a-t-il d'instituts régionaux d'administration (IRA), qui forment les attachés d'administration de l'État ?",o:["Trois","Treize","Vingt-deux","Cinq"],a:3,e:"Bastia, Lille, Lyon, Metz et Nantes.",u:["https://fr.wikipedia.org/wiki/Institut_r%C3%A9gional_d%27administration"],s:"Banque administration"},
{id:"ad2-149",t:"admin",q:"Comment s'appelle la réforme lancée en 2019 pour réorganiser la présence de la DGFiP dans les territoires, avec notamment des conseillers aux décideurs locaux ?",o:["La RéATE","Action publique 2022","Le nouveau réseau de proximité (NRP)","Le plan France Relance"],a:2,e:"Elle a aussi créé les services de gestion comptable (SGC), qui ont repris la tenue des comptes des collectivités assurée par les trésoreries.",s:"Banque administration"},
{id:"ad2-151",t:"admin",q:"Quelle loi, dite loi Le Pors, fixait les droits et obligations des fonctionnaires avant leur codification dans le code général de la fonction publique ?",o:["La loi du 19 octobre 1946","La loi du 6 août 2019","La loi du 20 avril 2016","La loi du 13 juillet 1983"],a:3,e:"Titre Ier du statut général, complété par les lois de 1984 (État et territoriale) et de 1986 (hospitalière).",u:["https://fr.wikipedia.org/wiki/Fonction_publique_fran%C3%A7aise"],s:"Banque administration"},
{id:"ad2-152",t:"admin",q:"Quel versant de la fonction publique emploie le plus d'agents ?",o:["La fonction publique de l'État","La fonction publique territoriale","La fonction publique hospitalière","Ils emploient chacun environ un tiers des agents"],a:0,e:"Environ 2,5 millions d'agents pour l'État, 2 millions pour la territoriale et 1,2 million pour l'hospitalière, sur environ 5,8 millions.",u:["https://fr.wikipedia.org/wiki/Fonction_publique_fran%C3%A7aise"],s:"Banque administration"},
{id:"ad2-153",t:"admin",q:"Dans la fonction publique, que garantit la distinction entre le grade et l'emploi ?",o:["Le fonctionnaire conserve à vie le même poste de travail","Le grade est attaché au poste occupé","Le grade appartient au fonctionnaire, l'emploi est à la disposition de l'administration","Un emploi ne peut jamais être supprimé"],a:2,e:"Le grade donne vocation à occuper l'un des emplois correspondants ; si son emploi est supprimé, le fonctionnaire conserve son grade.",u:["https://www.service-public.gouv.fr/particuliers/vosdroits/F12344"],s:"Banque administration"},
{id:"ad2-154",t:"admin",q:"Quel diplôme est en principe exigé pour se présenter au concours externe d'inspecteur des finances publiques (catégorie A) ?",o:["Le baccalauréat","Un master (bac + 5)","Aucun diplôme","Un diplôme de niveau licence (bac + 3)"],a:3,e:"Le concours externe de contrôleur des finances publiques (catégorie B) exige le baccalauréat.",s:"Banque administration"},
{id:"ad2-155",t:"admin",q:"À qui est ouvert le troisième concours de la fonction publique ?",o:["Aux fonctionnaires ayant échoué deux fois au concours interne","Aux candidats justifiant d'une expérience professionnelle privée, d'un mandat électif local ou d'une activité associative","Aux seuls titulaires d'un doctorat","Aux ressortissants d'États non membres de l'Union européenne"],a:1,e:"Le concours externe vise les candidats diplômés, le concours interne les agents publics en fonction.",u:["https://fr.wikipedia.org/wiki/Institut_r%C3%A9gional_d%27administration"],s:"Banque administration"},
{id:"ad2-156",t:"admin",q:"Laquelle de ces situations n'est pas une position statutaire du fonctionnaire ?",o:["Le congé de maladie","Le détachement","La disponibilité","Le congé parental"],a:0,e:"Les quatre positions sont l'activité, le détachement, la disponibilité et le congé parental ; le congé de maladie relève de la position d'activité.",u:["https://www.service-public.gouv.fr/particuliers/vosdroits/F12413"],s:"Banque administration"},
{id:"ad2-157",t:"admin",q:"Quelle position place le fonctionnaire hors de son corps d'origine tout en lui conservant, dans ce corps, ses droits à l'avancement et à la retraite ?",o:["La disponibilité","Le détachement","La mise à disposition","Le congé parental"],a:1,e:"Le fonctionnaire détaché est rémunéré par l'organisme d'accueil.",u:["https://www.service-public.gouv.fr/particuliers/vosdroits/F12413"],s:"Banque administration"},
{id:"ad2-158",t:"admin",q:"Quelle est la principale conséquence de la mise en disponibilité d'un fonctionnaire ?",o:["Il cesse d'être rémunéré par son administration","Il perd définitivement la qualité de fonctionnaire","Il conserve son traitement et ses primes","Il continue d'exercer ses fonctions à temps partiel"],a:0,e:"Placé hors de son administration d'origine, il peut, depuis 2019, conserver ses droits à avancement pendant 5 ans au plus s'il exerce une activité professionnelle.",u:["https://www.service-public.gouv.fr/particuliers/vosdroits/F544"],s:"Banque administration"},
{id:"ad2-159",t:"admin",q:"Quelle forme de grève est interdite dans la fonction publique ?",o:["La grève d'une journée","La grève précédée d'un préavis syndical","La grève tournante","La grève d'une heure"],a:2,e:"Sont également interdites la grève politique et la grève sans préavis.",u:["https://www.service-public.gouv.fr/particuliers/vosdroits/F499"],s:"Banque administration"},
{id:"ad2-160",t:"admin",q:"Dans la fonction publique de l'État, quelle retenue sur rémunération entraîne une grève d'une heure ?",o:["Une retenue proportionnelle à une heure de travail","Aucune retenue","Un soixantième de la rémunération mensuelle","Un trentième de la rémunération mensuelle"],a:3,e:"Règle du « trentième indivisible » ; dans la territoriale et l'hospitalière, la retenue est proportionnelle à la durée de la grève.",u:["https://www.service-public.gouv.fr/particuliers/vosdroits/F499"],s:"Banque administration"},
{id:"ad2-161",t:"admin",q:"Lequel de ces agents publics est privé du droit de grève ?",o:["Un agent des finances publiques","Un militaire","Un enseignant","Un agent territorial"],a:1,e:"Le droit de grève, reconnu par le Préambule de 1946, est aussi interdit notamment aux policiers, aux magistrats et aux personnels de surveillance pénitentiaire.",u:["https://www.service-public.gouv.fr/particuliers/vosdroits/F499"],s:"Banque administration"},
{id:"ad2-162",t:"admin",q:"Quelle loi a inscrit dans le statut général les obligations de dignité, d'impartialité, d'intégrité et de probité, ainsi que le respect du principe de laïcité ?",o:["La loi du 20 avril 2016 relative à la déontologie et aux droits et obligations des fonctionnaires","La loi du 13 juillet 1983","La loi du 6 août 2019","La loi du 24 août 2021"],a:0,e:"Elle a aussi créé le référent déontologue et renforcé la prévention des conflits d'intérêts.",u:["https://fr.wikipedia.org/wiki/Fonction_publique_fran%C3%A7aise"],s:"Banque administration"},
{id:"ad2-163",t:"admin",q:"Depuis la loi de 2016 sur la déontologie, que peut faire tout agent public qui s'interroge sur ses obligations déontologiques ?",o:["Saisir le Conseil constitutionnel","Demander un rescrit fiscal","Saisir directement la CNIL","Consulter un référent déontologue"],a:3,e:"Le référent apporte un conseil confidentiel sur le respect des obligations et principes déontologiques.",u:["https://www.service-public.gouv.fr/particuliers/vosdroits/F35129"],s:"Banque administration"},
{id:"ad2-164",t:"admin",q:"Un agent public peut-il porter un signe religieux visible dans l'exercice de ses fonctions ?",o:["Oui, s'il n'est pas en contact avec le public","Oui, sauf dans les établissements scolaires","Non, en raison de son obligation de neutralité","Oui, si son chef de service l'autorise"],a:2,e:"Avis Marteaux du Conseil d'État (2000) ; les usagers du service public peuvent en revanche manifester leurs convictions, sauf texte particulier.",u:["https://www.service-public.gouv.fr/particuliers/vosdroits/F530"],s:"Banque administration"},
{id:"ad2-165",t:"admin",q:"Depuis la loi du 24 août 2021 confortant le respect des principes de la République, chaque administration doit désigner :",o:["un délégué syndical","un médiateur fiscal","un aumônier","un référent laïcité"],a:3,e:"Il conseille les agents et les chefs de service sur l'application du principe de laïcité.",s:"Banque administration"},
{id:"ad2-166",t:"admin",q:"Quelle peine encourt un agent public qui révèle une information couverte par le secret professionnel, hors des cas autorisés ?",o:["Une simple sanction disciplinaire","Six mois d'emprisonnement et 7 500 € d'amende","Un an d'emprisonnement et 15 000 € d'amende","Cinq ans d'emprisonnement et 75 000 € d'amende"],a:2,e:"Article 226-13 du code pénal ; une sanction disciplinaire peut s'y ajouter.",u:["https://www.service-public.gouv.fr/particuliers/vosdroits/F530"],s:"Banque administration"},
{id:"ad2-167",t:"admin",q:"Sur quoi porte le devoir de réserve de l'agent public ?",o:["Sur le contenu de ses opinions, qu'il n'a pas le droit d'avoir","Sur le mode d'expression de ses opinions, pendant et en dehors du service","Uniquement sur les informations relatives aux usagers","Uniquement sur ses propos tenus pendant le temps de travail"],a:1,e:"Il ne supprime pas la liberté d'opinion ; son appréciation dépend notamment des fonctions exercées et de la publicité donnée aux propos.",u:["https://www.service-public.gouv.fr/particuliers/vosdroits/F530"],s:"Banque administration"},
{id:"ad2-168",t:"admin",q:"Laquelle de ces activités un fonctionnaire peut-il exercer librement, sans autorisation ?",o:["La production d'œuvres de l'esprit, comme l'écriture d'un livre","La direction d'une société commerciale","Un second emploi permanent à temps complet","Une activité de conseil rémunérée auprès d'une entreprise qu'il contrôle"],a:0,e:"Les activités accessoires (enseignement, expertise…) sont soumises à autorisation ; certaines activités sont interdites.",u:["https://www.service-public.gouv.fr/particuliers/vosdroits/F1648"],s:"Banque administration"},
{id:"ad2-169",t:"admin",q:"Un fonctionnaire à temps complet qui crée ou reprend une entreprise peut être autorisé à travailler à temps partiel pour une durée maximale de :",o:["trois ans, renouvelable pour un an","six mois","un an, non renouvelable","cinq ans"],a:0,e:"L'autorisation est accordée sous réserve des nécessités du service.",u:["https://www.service-public.gouv.fr/particuliers/vosdroits/F1648"],s:"Banque administration"},
{id:"ad2-170",t:"admin",q:"Comment la loi définit-elle le conflit d'intérêts pour un agent public ?",o:["Toute activité privée exercée en dehors des heures de service","Toute relation familiale entre deux agents d'un même service","Toute situation d'interférence entre un intérêt public et des intérêts publics ou privés de nature à influencer ou paraître influencer l'exercice indépendant, impartial et objectif de ses fonctions","Tout désaccord entre un agent et son supérieur hiérarchique"],a:2,e:"L'agent doit faire cesser immédiatement ou prévenir de telles situations.",s:"Banque administration"},
{id:"ad2-171",t:"admin",q:"Quelle sanction disciplinaire peut être infligée à un fonctionnaire de l'État sans consultation du conseil de discipline ?",o:["Le déplacement d'office","La rétrogradation","La révocation","Le blâme"],a:3,e:"Les sanctions du 1er groupe (avertissement, blâme, exclusion temporaire de 1 à 3 jours) sont prononcées sans conseil de discipline.",u:["https://www.service-public.gouv.fr/particuliers/vosdroits/F510"],s:"Banque administration"},
{id:"ad2-172",t:"admin",q:"Quelle sanction relève du troisième groupe dans la fonction publique de l'État ?",o:["L'avertissement","L'exclusion temporaire de fonctions de 16 jours à 2 ans","Le déplacement d'office","La révocation"],a:1,e:"Le 3e groupe comprend aussi la rétrogradation ; le 4e groupe, la mise à la retraite d'office et la révocation.",u:["https://www.service-public.gouv.fr/particuliers/vosdroits/F510"],s:"Banque administration"},
{id:"ad2-173",t:"admin",q:"Au bout de combien de temps le blâme est-il effacé automatiquement du dossier du fonctionnaire, si aucune autre sanction n'est intervenue ?",o:["Un an","Cinq ans","Trois ans","Dix ans"],a:2,e:"L'avertissement n'est pas inscrit au dossier ; pour les sanctions des 2e et 3e groupes, l'agent peut demander l'effacement après 10 ans de services.",u:["https://www.service-public.gouv.fr/particuliers/vosdroits/F510"],s:"Banque administration"},
{id:"ad2-174",t:"admin",q:"Dans quel délai l'administration doit-elle engager une procédure disciplinaire contre un fonctionnaire ?",o:["Deux mois à compter des faits","Six mois à compter des faits","Aucun délai ne s'applique","Trois ans à compter du jour où elle a eu connaissance effective des faits"],a:3,e:"Délai issu de la loi du 20 avril 2016 ; il est interrompu en cas de poursuites pénales.",u:["https://www.service-public.gouv.fr/particuliers/vosdroits/F510"],s:"Banque administration"},
{id:"ad2-175",t:"admin",q:"Quelle est la nature de la suspension d'un fonctionnaire auteur d'une faute grave ?",o:["Une sanction disciplinaire du premier groupe","Une mesure conservatoire, prise dans l'intérêt du service, qui n'est pas une sanction","Une sanction pénale","Une mise en disponibilité d'office"],a:1,e:"Le fonctionnaire suspendu conserve en principe son traitement ; sa situation doit être réglée dans un délai de quatre mois, sauf poursuites pénales.",u:["https://www.service-public.gouv.fr/particuliers/vosdroits/F510"],s:"Banque administration"},
{id:"ad2-176",t:"admin",q:"Dans quel cas l'administration peut-elle refuser la protection fonctionnelle à un agent mis en cause pour des faits commis dans ses fonctions ?",o:["En cas de faute personnelle détachable de l'exercice de ses fonctions","Si l'agent est contractuel","Si l'agent est de catégorie C","Si les faits se sont produits pendant les heures de service"],a:0,e:"Hors faute personnelle, la collectivité publique doit protéger l'agent contre les attaques et le couvrir des condamnations civiles.",u:["https://www.service-public.gouv.fr/particuliers/vosdroits/F32574"],s:"Banque administration"},
{id:"ad2-177",t:"admin",q:"Quelle loi a créé, en 2016, un statut général du lanceur d'alerte ?",o:["La loi Sapin 2 du 9 décembre 2016","La loi du 20 avril 2016 sur la déontologie","La loi pour une République numérique","La loi ESSOC"],a:0,e:"Ce statut a été renforcé par la loi Waserman du 21 mars 2022.",u:["https://www.service-public.gouv.fr/particuliers/vosdroits/F34665"],s:"Banque administration"},
{id:"ad2-178",t:"admin",q:"Depuis la loi du 21 mars 2022, un agent public lanceur d'alerte :",o:["doit d'abord saisir son supérieur hiérarchique","doit d'abord rendre les faits publics dans la presse","peut signaler les faits en interne ou directement à une autorité externe, à son choix","ne peut saisir que le procureur de la République"],a:2,e:"Les autorités externes comprennent notamment le Défenseur des droits, la justice et les autorités compétentes désignées par décret.",u:["https://www.service-public.gouv.fr/particuliers/vosdroits/F34665"],s:"Banque administration"},
{id:"ad2-179",t:"admin",q:"Quelle est la durée annuelle de référence du travail effectif d'un agent à temps complet dans la fonction publique ?",o:["1 470 heures","1 820 heures","1 500 heures","1 607 heures"],a:3,e:"Soit 35 heures hebdomadaires, journée de solidarité comprise.",s:"Banque administration"},
{id:"ad2-180",t:"admin",q:"Dans la fonction publique, combien de jours de télétravail par semaine un agent à temps plein peut-il obtenir au plus, en principe ?",o:["Deux","Trois","Quatre","Cinq"],a:1,e:"Sa présence sur site ne peut être inférieure à deux jours par semaine, sauf dérogations (santé, handicap, grossesse, proche aidant…).",u:["https://www.service-public.gouv.fr/particuliers/vosdroits/F13974"],s:"Banque administration"},
{id:"ad2-181",t:"admin",q:"Quelle instance a remplacé, après les élections professionnelles de décembre 2022, les comités techniques et les CHSCT dans la fonction publique de l'État ?",o:["La commission administrative paritaire (CAP)","Le conseil de discipline","Le comité social d'administration (CSA)","Le comité économique et social"],a:2,e:"Création par la loi du 6 août 2019 ; l'instance s'appelle comité social territorial dans la territoriale et comité social d'établissement dans l'hospitalière.",s:"Banque administration"},
{id:"ad2-182",t:"admin",q:"Depuis la loi du 6 août 2019, sur quelles décisions individuelles les CAP ne sont-elles plus consultées ?",o:["Les sanctions disciplinaires des 2e à 4e groupes","Les mutations et les promotions","Les refus de titularisation","Les licenciements pour insuffisance professionnelle"],a:1,e:"Ces décisions s'appuient désormais sur des lignes directrices de gestion (LDG).",s:"Banque administration"},
{id:"ad2-183",t:"admin",q:"Quel contrat, créé par la loi du 6 août 2019, permet de recruter un agent pour mener à bien un projet identifié, pour une durée d'un à six ans ?",o:["Le contrat de projet","Le contrat à durée indéterminée","Le contrat d'apprentissage","Le contrat de mission temporaire"],a:0,e:"Il prend fin avec la réalisation du projet et ne donne droit ni à un CDI ni à une titularisation.",u:["https://www.service-public.gouv.fr/particuliers/vosdroits/F35145"],s:"Banque administration"},
{id:"ad2-184",t:"admin",q:"Dans la fonction publique, la rupture conventionnelle :",o:["est une sanction disciplinaire","est décidée unilatéralement par l'administration","est réservée aux agents de plus de 60 ans","résulte d'un accord entre l'agent et l'administration et ne peut être imposée par aucune des deux parties"],a:3,e:"Créée par la loi du 6 août 2019, elle ouvre droit à une indemnité spécifique ; elle se distingue de la démission (décision de l'agent) et du licenciement (décision de l'administration).",u:["https://www.service-public.gouv.fr/particuliers/vosdroits/F31094"],s:"Banque administration"},
{id:"ad2-185",t:"admin",q:"Quelle école assure la formation initiale des inspecteurs et des contrôleurs des finances publiques ?",o:["L'Institut national du service public","Un institut régional d'administration","L'École nationale de la magistrature","L'École nationale des finances publiques (ENFiP)"],a:3,e:"Service à compétence nationale de la DGFiP.",u:["https://fr.wikipedia.org/wiki/Direction_g%C3%A9n%C3%A9rale_des_Finances_publiques"],s:"Banque administration"},
{id:"ad2-186",t:"admin",q:"Que permet le droit de retrait à un agent public ?",o:["Refuser toute mutation","Quitter son poste sans préavis pour convenance personnelle","Se retirer d'une situation de travail présentant un danger grave et imminent pour sa vie ou sa santé","Refuser d'appliquer une loi qu'il juge injuste"],a:2,e:"Aucune sanction ni retenue sur rémunération ne peut être prise si le retrait est justifié ; l'agent doit alerter son supérieur.",s:"Banque administration"},
{id:"ad2-187",t:"admin",q:"Quelle direction, rattachée au directeur général des Finances publiques, prépare les textes fiscaux et leurs instructions d'application ?",o:["La direction de la législation fiscale (DLF)","La direction du Budget","La direction générale du Trésor","La direction des affaires juridiques"],a:0,e:"Elle représente aussi le ministère dans les négociations fiscales internationales.",u:["https://fr.wikipedia.org/wiki/Direction_g%C3%A9n%C3%A9rale_des_Finances_publiques"],s:"Banque administration"},
{id:"ad2-188",t:"admin",q:"Quel service rattaché à la DGFiP gère les pensions de retraite des fonctionnaires de l'État ?",o:["La Caisse nationale d'assurance vieillesse","Le service des retraites de l'État (SRE)","L'Agirc-Arrco","La Caisse des dépôts et consignations"],a:1,e:"Établi à Nantes, il gère le compte d'affectation spéciale « Pensions ».",u:["https://fr.wikipedia.org/wiki/Direction_g%C3%A9n%C3%A9rale_des_Finances_publiques"],s:"Banque administration"},
{id:"ad2-189",t:"admin",q:"Quelle direction de la DGFiP, qui a succédé à France Domaine en 2016, pilote la politique immobilière de l'État ?",o:["L'Agence des participations de l'État","La direction des achats de l'État","La direction de l'immobilier de l'État (DIE)","L'Agence France Trésor"],a:2,e:"Elle est l'héritière de l'administration des Domaines.",u:["https://fr.wikipedia.org/wiki/Direction_de_l%27immobilier_de_l%27%C3%89tat"],s:"Banque administration"},
{id:"ad2-190",t:"admin",q:"Quelle direction de la DGFiP est l'interlocuteur fiscal unique des entreprises dont le chiffre d'affaires ou l'actif brut atteint au moins 400 millions d'euros ?",o:["La direction des grandes entreprises (DGE)","La direction des vérifications nationales et internationales (DVNI)","Le service des impôts des entreprises de leur siège","La direction nationale des enquêtes fiscales (DNEF)"],a:0,e:"Elle gère au quotidien leurs déclarations et leurs paiements (TVA, impôt sur les sociétés…).",u:["https://fr.wikipedia.org/wiki/Direction_des_grandes_entreprises"],s:"Banque administration"},
{id:"ad2-191",t:"admin",q:"Quelle direction nationale de la DGFiP est chargée du contrôle fiscal des plus grandes entreprises ?",o:["La direction des grandes entreprises (DGE)","La direction nationale des enquêtes fiscales (DNEF)","La direction de la législation fiscale (DLF)","La direction des vérifications nationales et internationales (DVNI)"],a:3,e:"Elle dispose de brigades spécialisées (informatique, finance, prix de transfert).",u:["https://fr.wikipedia.org/wiki/Direction_g%C3%A9n%C3%A9rale_des_Finances_publiques"],s:"Banque administration"},
{id:"ad2-192",t:"admin",q:"Quelle direction nationale de la DGFiP est spécialisée dans la recherche des circuits de fraude fiscale et le renseignement ?",o:["La direction des grandes entreprises (DGE)","La direction nationale des enquêtes fiscales (DNEF)","Le service des impôts des particuliers","La direction de l'immobilier de l'État"],a:1,e:"Elle travaille notamment en lien avec la police judiciaire.",u:["https://fr.wikipedia.org/wiki/Direction_g%C3%A9n%C3%A9rale_des_Finances_publiques"],s:"Banque administration"},
{id:"ad2-193",t:"admin",q:"Quel service de la DGFiP est l'interlocuteur fiscal unique des professionnels (PME, artisans, professions libérales) pour leurs principaux impôts ?",o:["Le service des impôts des particuliers (SIP)","Le service de la publicité foncière","Le service des impôts des entreprises (SIE)","La trésorerie hospitalière"],a:2,e:"Il gère notamment la TVA, l'impôt sur les sociétés et la cotisation foncière des entreprises.",u:["https://fr.wikipedia.org/wiki/Direction_g%C3%A9n%C3%A9rale_des_Finances_publiques"],s:"Banque administration"},
{id:"ad2-194",t:"admin",q:"Quel service de la DGFiP a remplacé les conservations des hypothèques le 1er janvier 2013 ?",o:["Le service des impôts des entreprises","Le centre des impôts foncier","La direction de l'immobilier de l'État","Le service de la publicité foncière"],a:3,e:"Il tient le fichier immobilier, qui assure la publicité des actes relatifs aux droits sur les immeubles.",s:"Banque administration"},
{id:"ad2-195",t:"admin",q:"Comment s'appelle le contrôle approfondi, sur place, de la cohérence entre les revenus déclarés par un particulier et sa situation patrimoniale et son train de vie ?",o:["La vérification de comptabilité","L'examen contradictoire de la situation fiscale personnelle (ESFP)","Le contrôle sur pièces","La procédure de rescrit"],a:1,e:"La vérification de comptabilité concerne les entreprises ; le contrôle sur pièces est mené depuis le bureau.",s:"Banque administration"},
{id:"ad2-196",t:"admin",q:"Quel document doit être remis au contribuable avant le début d'une vérification de comptabilité ?",o:["La charte des droits et obligations du contribuable vérifié","Une mise en demeure de payer","Un avis de mise en recouvrement","La liste des agents habilités à le contrôler"],a:0,e:"Elle est jointe à l'avis de vérification ; ses dispositions sont opposables à l'administration (art. L. 10 du livre des procédures fiscales).",s:"Banque administration"},
{id:"ad2-197",t:"admin",q:"Quel article du livre des procédures fiscales pose le secret professionnel en matière fiscale ?",o:["L'article L. 103","L'article L. 10","L'article L. 169","L'article L. 52"],a:0,e:"Il s'impose à toutes les personnes appelées à intervenir dans l'établissement, le contrôle, le recouvrement ou le contentieux des impôts.",s:"Banque administration"},
{id:"ad2-198",t:"admin",q:"Le secret fiscal peut-il être levé ?",o:["Oui, à la demande de tout journaliste","Non, jamais, même au profit de la justice","Oui, uniquement dans les cas prévus par la loi, au profit de certaines autorités (justice, organismes sociaux…)","Oui, sur simple demande d'un élu local"],a:2,e:"Ces dérogations sont limitativement énumérées par le livre des procédures fiscales.",s:"Banque administration"},
{id:"ad2-199",t:"admin",q:"La liste des personnes assujetties à l'impôt sur le revenu (art. L. 111 du livre des procédures fiscales) :",o:["est publiée chaque année au Journal officiel","est librement accessible sur internet","ne peut être consultée que par le maire","peut être consultée par les contribuables relevant de la direction qui la tient, mais sa publication ou sa diffusion est interdite"],a:3,e:"Toute publication ou diffusion de ces informations est sanctionnée par une amende fiscale.",s:"Banque administration"},
{id:"ad2-200",t:"admin",q:"Depuis le 1er janvier 2019, quelle procédure unique permet aux comptables publics de faire saisir des sommes détenues par un tiers (banque, employeur) pour le compte d'un débiteur ?",o:["L'avis à tiers détenteur","La saisie administrative à tiers détenteur (SATD)","L'opposition à tiers détenteur","La saisie-attribution par commissaire de justice"],a:1,e:"Elle a remplacé notamment l'avis à tiers détenteur et l'opposition à tiers détenteur.",s:"Banque administration"},
{id:"ad2-201",t:"admin",q:"Hors transmission automatique au parquet, quelle commission doit en principe émettre un avis favorable avant que l'administration dépose plainte pour fraude fiscale ?",o:["La commission départementale des impôts directs","La commission des infractions fiscales (CIF)","Le comité de l'abus de droit fiscal","La commission nationale des impôts directs et des taxes sur le chiffre d'affaires"],a:1,e:"Depuis la loi du 23 octobre 2018, les dossiers les plus graves sont transmis automatiquement au procureur de la République.",s:"Banque administration"},
{id:"ad2-202",t:"admin",q:"Depuis la loi du 23 octobre 2018 relative à la lutte contre la fraude, quand l'administration fiscale doit-elle dénoncer automatiquement des faits au procureur de la République ?",o:["Dès que le contribuable conteste le redressement","Lorsque les droits rappelés dépassent 10 000 €","Lorsque les droits rappelés dépassent 100 000 € et sont assortis de certaines majorations","Après tout contrôle sur pièces"],a:2,e:"Cette réforme a assoupli le « verrou de Bercy » ; les autres dossiers restent soumis à l'avis de la commission des infractions fiscales.",s:"Banque administration"},
{id:"ad2-203",t:"admin",q:"Laquelle de ces missions relève de la DGFiP ?",o:["La perception des droits de douane","L'élaboration du budget de l'État","La gestion de la dette négociable de l'État","La tenue des comptes de l'État et le paiement de ses dépenses"],a:3,e:"Les droits de douane relèvent de la DGDDI, la préparation du budget de la direction du Budget et la dette de l'Agence France Trésor.",u:["https://fr.wikipedia.org/wiki/Direction_g%C3%A9n%C3%A9rale_des_Finances_publiques"],s:"Banque administration"},
{id:"ad2-204",t:"admin",q:"Outre leur nombre (500), quelle condition s'applique aux présentations (« parrainages ») d'un candidat à l'élection présidentielle ?",o:["Elles doivent venir d'au moins 30 départements ou collectivités d'outre-mer, et pas plus d'un dixième d'un même département","Elles doivent venir de chacune des 18 régions","Elles doivent venir uniquement de maires","Aucune : seul le nombre de 500 compte"],a:0,e:"Loi du 6 novembre 1962 : un candidat ne peut donc pas réunir plus de 50 parrainages dans un même département.",x:"Depuis la loi organique du 25 avril 2016, les élus envoient eux-mêmes leur présentation au Conseil constitutionnel, qui publie la liste intégrale des parrains.",u:["https://www.elections.interieur.gouv.fr/scrutins/lelection-presidentielle"],s:"Loi n° 62-1292 du 6 novembre 1962, art. 3"}
);
